ON CONFLICT (skill, source_key) DO UPDATE SET
  part_number = EXCLUDED.part_number,
  question_type = EXCLUDED.question_type,
  source_file = EXCLUDED.source_file,
  content = EXCLUDED.content,
  display_order = EXCLUDED.display_order,
  ui_config = EXCLUDED.ui_config,
  metadata = EXCLUDED.metadata,
  content_hash = EXCLUDED.content_hash
WHERE aptis_questions.content IS DISTINCT FROM EXCLUDED.content
   OR aptis_questions.ui_config IS DISTINCT FROM EXCLUDED.ui_config
   OR aptis_questions.metadata IS DISTINCT FROM EXCLUDED.metadata
   OR aptis_questions.content_hash IS DISTINCT FROM EXCLUDED.content_hash;

