INSERT INTO public.aptis_question_answers (question_id, solution_data)
SELECT q.id, a.solution_data::jsonb
FROM (VALUES
  ('speaking-p1-topic001-q001', '{"sample_answer":"In my free time, I enjoy going out for food with my friends, because it''s a great way to relax after a busy week. We often try new restaurants, enjoy delicious food, and talk about our studies or future plans. I always look forward to those moments.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic001-q002', '{"sample_answer":null,"sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":true,"missing_rubric":true}}'),
  ('speaking-p1-topic001-q003', '{"sample_answer":"[Last night / On the weekend], I went out for dinner with some friends at a small restaurant. We ordered some simple but delicious food and talked about our studies and future plans. The atmosphere was relaxing, so I felt happy and comfortable. It was a simple evening, but we really enjoyed spending time together.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic001-q004', '{"sample_answer":"One of my favorite memories was going out for food with my friends after a busy week. We tried a new restaurant, enjoyed delicious food, and talked about our studies or future plans. It was a simple moment, but we had a great time together and I still remember it clearly.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic001-q005', '{"sample_answer":"My favorite place is restaurants because I really enjoy going out for food with my friends. I like the warm atmosphere, the delicious food, and the time we spend talking together. It always makes me feel relaxed and happy.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic002-q001', '{"sample_answer":"I''m currently a university student at Sai Gon University, majoring in Information Technology. I''m always learning English while improving my programming skills because I want to become a software engineer. That''s why I try my best every day.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic002-q002', '{"sample_answer":"On a typical day, I usually attend classes, study programming, and practise English. In the evening, I review what I''ve learned or work on personal projects. Before going to bed, I often plan my tasks for the next day.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic002-q003', '{"sample_answer":"I''m learning English because it''s important for my studies and future career. It helps me communicate with more people and read technical documents. I also believe it will open up better opportunities in the future.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic002-q004', '{"sample_answer":"I''m learning English because it''s important for my studies and future career. It helps me communicate with more people and read technical documents. I also believe it will open up better opportunities in the future.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic002-q005', '{"sample_answer":"I usually feel [stressed / tired] when I have too many things to do and not enough time to rest. It often happens when I have multiple assignments and deadlines at the same time, which makes it difficult for me to stay focused and manage my work effectively.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic003-q001', '{"sample_answer":"There are four people in my family: my parents, my younger brother, and me. My parents have always encouraged me to pursue my goals and supported me whenever I face difficulties. As for my younger brother, he always manages to make everyone laugh. I feel fortunate to have such a caring family.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic003-q002', '{"sample_answer":"I''d like to talk about [my mother / my close friend]. She is kind, patient, and incredibly supportive. She always encourages me to keep learning and never give up. What I admire most about her is her positive attitude.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic003-q003', '{"sample_answer":"The last time I talked with my mother was recently. We talked about my studies, my future plans, and some everyday things. She encouraged me to stay patient and keep working hard, which made me feel more confident.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic004-q001', '{"sample_answer":"[My hometown is / I live in / One famous place in Vietnam is] Ho Chi Minh City is one of the most vibrant and dynamic cities in Vietnam. There are many cafés, shopping centres, and universities. Although the traffic is quite stressful, I still like its energy and fast-paced life.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic004-q002', '{"sample_answer":"The best way to travel depends on the distance. For long trips, flying is the fastest and most convenient option. For shorter trips, I prefer trains or motorbikes because they are more affordable and flexible.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic004-q003', '{"sample_answer":"My journey here today was quite smooth. I left home on time and travelled by motorbike. The traffic was a bit busy, but everything went well. I arrived safely and felt ready for the test.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic005-q001', '{"sample_answer":"[A typical Vietnamese meal is usually / Food in Vietnam is] simple, balanced, and full of flavour. t often includes rice, vegetables, soup, and a main dish like fish, chicken, or pork. I think Vietnamese food is healthy and delicious because it uses a lot of fresh ingredients.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic005-q002', '{"sample_answer":"Yes, many people in Vietnam enjoy sports, especially football. They often watch matches with friends or family. Other popular sports include badminton, volleyball, and running because they help people stay healthy and reduce stress.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic005-q003', '{"sample_answer":"One famous book in Vietnam is Kính Vạn Hoa by Nguyễn Nhật Ánh. I like it because it is simple, funny, and meaningful. It tells interesting stories about childhood and friendship, and it reminds readers of the joy of growing up.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic005-q004', '{"sample_answer":"[The weather today is quite cool and pleasant / My favourite season is autumn]. It is not too hot or too cold, which makes it perfect for going outside, studying, or travelling. I always feel more comfortable and energetic in this kind of weather.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic005-q005', '{"sample_answer":"My first school was quite small, but it was a very memorable place for me. I met my first teachers and made my first friends there. The teachers were kind and patient, so I always felt comfortable and enjoyed learning as a child.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic005-q006', '{"sample_answer":"My room is quite simple but comfortable. It has everything I need, such as a desk, a bed, and my laptop. I usually use it for studying, practising English, and relaxing after a long day. I like it because it is quiet and helps me focus better.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic005-q007', '{"sample_answer":"Today, I am wearing a simple white shirt and black trousers. I also have a pair of sneakers. My outfit is quite casual and comfortable, suitable for studying and taking a test. It helps me feel relaxed and confident during the day.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic005-q008', '{"sample_answer":"I would like a new house in a quiet and safe area. It should have enough space for studying and relaxing, with good natural light and fresh air. I also prefer a convenient location, close to public transport and basic facilities like shops and cafes.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic005-q009', '{"sample_answer":"I am interested in travelling because it allows me to explore new places and experience different cultures. I also enjoy trying local food and meeting new people. Travelling helps me relax after studying or working and gives me more motivation in life.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic006-q001', '{"sample_answer":"In the afternoon, I usually attend classes or complete important study tasks. During the evening, I review programming concepts, practise English, or work on a personal project. I also take a short walk and talk with my family. This routine helps me remain productive without allowing study to occupy every available hour.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic006-q002', '{"sample_answer":"In the afternoon, I usually attend classes or complete important study tasks. During the evening, I review programming concepts, practise English, or work on a personal project. I also take a short walk and talk with my family. This routine helps me remain productive without allowing study to occupy every available hour.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic007-q001', '{"sample_answer":"I normally go out two or three times a week, usually after class or at the weekend. I might meet friends at a café, have dinner, or walk around a shopping area. I enjoy going out, but I also protect quiet evenings for studying and resting, so I try to maintain a sensible balance.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic007-q002', '{"sample_answer":"I usually go out with a small group of close university friends. We have similar interests and can talk comfortably about study, work, and everyday life. Occasionally, I go out with my family for a meal. I prefer familiar company because the experience feels more relaxed and conversations are usually more meaningful.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic007-q003', '{"sample_answer":"When I go out, I often visit an independent café or an affordable restaurant near my university. These places are convenient, comfortable, and suitable for conversation. Sometimes my friends and I explore a bookshop or walk through a public park. We prefer locations where we can relax without spending excessively.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic007-q004', '{"sample_answer":"I enjoy small parties where I can speak comfortably with people I know. Large, extremely noisy events can feel tiring, but a relaxed birthday or graduation celebration is enjoyable. Good food, music, and meaningful conversation create a pleasant atmosphere. For me, the company matters much more than expensive decorations or entertainment.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic007-q005', '{"sample_answer":"At a party, I usually greet the host, talk with friends, try some food, and take photographs. If music is playing, I may join simple games rather than dance confidently. I also offer to help organise or clean up. Participating actively makes the event warmer and prevents me from feeling like a passive guest.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic007-q006', '{"sample_answer":"My family normally holds a party for birthdays, graduations, weddings, or major holidays such as Tet. We prefer manageable gatherings where relatives can share food and conversation. The purpose is not simply entertainment; these occasions help maintain relationships, celebrate achievements, and create memories that people may value for many years.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic007-q007', '{"sample_answer":"I had a fairly large group of friends when I was small because many children lived in the same neighbourhood. We attended nearby schools and played outside most evenings. Although I am no longer in contact with everyone, those friendships taught me cooperation, compromise, and how to resolve small disagreements independently.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic007-q008', '{"sample_answer":"I last met friends at a café about a week ago after university classes. We chose a quiet place nearby, ordered coffee, and discussed our assignments and career plans. We also laughed about several campus experiences. The meeting lasted only two hours, but it helped everyone relax after a demanding week.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic008-q001', '{"sample_answer":"I am currently studying Information Technology at Sai Gon University. My course involves programming, databases, and software development, which can be challenging but rewarding. Alongside my degree, I practise English and build personal projects because I hope to become a capable software engineer and work in a professional international environment.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic008-q002', '{"sample_answer":"Yes, I have attended a university interview for a group project and a practice job interview. The experience was initially intimidating because I had to answer unexpected questions. However, it taught me to organise ideas quickly, support answers with examples, and maintain professional body language even when I felt nervous.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic008-q003', '{"sample_answer":"Before an interview, I research the organisation, review the role or course requirements, and prepare examples that demonstrate relevant skills. I also practise common questions aloud, check my documents, and plan the journey. Careful preparation reduces avoidable stress and allows me to focus on communicating clearly rather than remembering basic information.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic008-q004', '{"sample_answer":"During my most recent practice interview, I felt nervous at first because I was concentrating on grammar and trying to answer perfectly. After the opening questions, I became calmer and spoke more naturally. The feedback showed that clear structure and specific examples matter more than using unnecessarily complicated language.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic008-q005', '{"sample_answer":"I am currently a university student rather than a full-time employee, but I am preparing for a career in backend software development. I study programming, databases, and system design while building practical projects. My goal is to join a supportive technology company where I can contribute, receive feedback, and develop professionally.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic008-q006', '{"sample_answer":"I do not currently have a regular part-time job because I am prioritising my final university work and technical portfolio. However, I would consider a flexible internship related to software development. Relevant experience would be more valuable than an unrelated job, provided the schedule still allowed me to study and maintain my health.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic008-q007', '{"sample_answer":"A part-time job can provide income, practical experience, and stronger time-management skills. Students learn to communicate with colleagues, accept responsibility, and understand workplace expectations before graduating. However, the hours should remain manageable. If employment damages academic performance or health, the short-term income may not justify the long-term cost.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic009-q001', '{"sample_answer":"My family spends most of its shared time in the living room. We eat light snacks, watch news or films, and discuss everyday plans there. The space is comfortable and central to the house, so everyone naturally gathers in it. It plays an important role in maintaining regular family communication.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic009-q002', '{"sample_answer":"I usually celebrate my birthday with a simple family meal and a small gathering of close friends. We share food, take photographs, and talk rather than organise an expensive event. I prefer this relaxed approach because it feels personal and allows me to spend meaningful time with the people who genuinely matter to me.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic009-q003', '{"sample_answer":"The best birthday gift I have received was a laptop from my family when I began studying Information Technology. It was valuable not only because of its price but because it supported my education and personal projects. The gift represented their confidence in my goals, so I have tried to use it responsibly.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic009-q004', '{"sample_answer":"For my next birthday, I plan to have dinner with my family and meet a few close friends at a café. I may also take a short day trip if everyone is available. I do not need a large celebration; I would rather enjoy relaxed conversations and create a few memorable photographs.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic009-q005', '{"sample_answer":"Yes, I enjoyed my childhood because it was relatively simple and full of time with family and neighbourhood friends. We played outside, invented games, and worried less about schedules or technology. There were ordinary difficulties, but I remember feeling supported and curious. Those experiences shaped my confidence and appreciation of close relationships.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic009-q006', '{"sample_answer":"The most memorable part of my childhood was playing hide-and-seek with neighbourhood friends after school. We used trees and house entrances as hiding places and often continued until dinner. The game itself was simple, but the freedom, laughter, and strong sense of friendship made those afternoons particularly meaningful to me.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic009-q007', '{"sample_answer":"My younger brother occasionally plays football with friends, while my parents prefer walking for exercise. None of us competes seriously, but we recognise the importance of staying active. At weekends, we sometimes take a walk together. Shared exercise is enjoyable and encourages everyone to maintain healthier routines.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic010-q001', '{"sample_answer":"My favourite room is my bedroom because it serves as both a private retreat and a practical study space. It contains a desk, laptop, bookshelf, and comfortable bed. The room is quiet enough for programming and English practice. After a demanding day, I can also listen to music and relax there.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic010-q002', '{"sample_answer":"In my favourite room, I study programming, practise English, attend online lessons, and work on personal projects. When I need a break, I listen to music or watch a short film. Because everything I regularly use is organised nearby, the room allows me to switch efficiently between focused work and relaxation.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic010-q003', '{"sample_answer":"I would improve my room by adding better task lighting, a more supportive chair, and a few plants near the window. These changes would make long study sessions more comfortable and create a fresher atmosphere. I would also add storage so that books and equipment remain organised rather than occupying valuable desk space.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic010-q004', '{"sample_answer":"I currently live in a house with my family. It is not particularly large or luxurious, but it is comfortable and located near essential shops. I appreciate having enough space to study and spend time together. The main disadvantage is traffic noise, especially during busy periods of the day.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic010-q005', '{"sample_answer":"I live with my parents and younger brother. We have different routines, but we usually meet at dinner and discuss our day. Living together provides emotional support and allows us to share household responsibilities. Although I sometimes want more privacy, I value the security and sense of belonging that family life provides.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic011-q001', '{"sample_answer":"My neighbourhood is a fairly convenient residential area with cafés, small shops, schools, and access to public transport. It can become busy during rush hour, but the side streets are relatively peaceful. I particularly appreciate the friendly local atmosphere and the fact that most daily necessities are within walking distance.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic011-q002', '{"sample_answer":"What I like most about my neighbourhood is its convenience. I can reach shops, cafés, and public transport within a few minutes, yet several streets remain quiet enough for an evening walk. The neighbours are generally polite and helpful, which creates a reassuring sense of community despite living in a large city.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic011-q003', '{"sample_answer":"I may remain in my current neighbourhood for the next few years because it is convenient for university and daily life. In the longer term, however, I would consider moving to a quieter area with more green space. My decision would depend on employment opportunities, transport connections, and housing costs.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic011-q004', '{"sample_answer":"Walking in the countryside is often more relaxing because the air is cleaner, the scenery is attractive, and traffic is limited. City walking, however, is more practical for daily routines and provides access to shops or public transport. I prefer the countryside for leisure, but the city is more convenient on weekdays.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic011-q005', '{"sample_answer":"The part of Ho Chi Minh City I like best is the central riverside area. It combines modern buildings, walking spaces, cafés, and several cultural landmarks. In the evening, the lights create an energetic atmosphere. Although it can be crowded, it is an interesting place to meet friends and observe the city''s development.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic011-q006', '{"sample_answer":"I like the central riverside area because it offers both impressive city views and convenient public spaces. I can walk, take photographs, visit a café, or reach nearby landmarks easily. The mixture of older architecture and modern buildings gives the area character, while the busy atmosphere reflects Ho Chi Minh City''s ambition and energy.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic011-q007', '{"sample_answer":"I would add more trees, shaded seating, and protected walking or cycling paths to my favourite city area. These changes would reduce heat, improve safety, and encourage healthier transport. I would also limit unnecessary traffic at peak times and provide more public bins so that the riverside remains clean, attractive, and accessible.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic011-q008', '{"sample_answer":"A beautiful place in Ho Chi Minh City is the riverside near the central district. Modern buildings reflect on the water, while walking areas and evening lights create an impressive atmosphere. It is especially attractive after sunset, when the temperature becomes cooler. Visitors can walk, take photographs, and explore nearby landmarks.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic011-q009', '{"sample_answer":"The most convenient way to reach the central riverside is by metro or bus, followed by a short walk. Public transport avoids parking difficulties and reduces stress in heavy traffic. A motorbike is flexible, but visitors unfamiliar with the city may find it challenging. I would therefore recommend the metro whenever possible.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic011-q010', '{"sample_answer":"The best time to visit the riverside is in the late afternoon or early evening. The weather is cooler, natural light is suitable for photographs, and the city gradually becomes illuminated. Weekdays are preferable because the area is less crowded, allowing visitors to walk comfortably and appreciate the view.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic011-q011', '{"sample_answer":"I once visited a traditional pottery village during a family trip. I watched craftspeople shape clay by hand, learned about the firing process, and tried making a small object myself. The experience was memorable because it revealed the patience behind handmade products and showed how local knowledge can be passed between generations.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic011-q012', '{"sample_answer":"My favourite traditional village is Bát Tràng pottery village near Hanoi. It is well known for skilled craftspeople, distinctive ceramics, and a long cultural history. Visitors can explore workshops, buy locally made products, and try shaping clay. The village successfully combines heritage preservation with tourism and practical creative experiences.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic011-q013', '{"sample_answer":"Traditional villages can be preserved by training younger craftspeople, documenting specialised techniques, and supporting fair markets for handmade products. Local authorities should protect historic spaces while improving facilities responsibly. Schools and tourism programmes can also introduce visitors to the culture, provided commercial development does not replace the community''s authentic character.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic011-q014', '{"sample_answer":"In Ho Chi Minh City, the best option depends on the route, but the metro and buses are increasingly practical for major corridors. Motorbikes remain flexible for short journeys, although traffic can be stressful. I prefer combining public transport with walking because it reduces parking problems and is generally more sustainable.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic012-q001', '{"sample_answer":"My most recent journey was a short family trip to Da Lat. We travelled by coach, watched the landscape change along the way, and stopped for local food. Although the winding road was slightly tiring, the cool weather and peaceful scenery made the experience worthwhile. It was a welcome break from city life.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic012-q002', '{"sample_answer":"A place I would always return to is Da Lat, a highland city known for cool weather, pine forests, and a peaceful atmosphere. I enjoy walking around the lake, trying local food, and visiting small cafés. Compared with Ho Chi Minh City, it feels slower and gives me space to recharge mentally.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic012-q003', '{"sample_answer":"I normally prefer visiting a special place with one or two people I know well. Sharing the journey makes it safer and allows us to create memories together. However, I still value a little time alone for walking or taking photographs. A small group offers the best balance between companionship and independence.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic012-q004', '{"sample_answer":"A place I would always return to is Da Lat, a highland city known for cool weather, pine forests, and a peaceful atmosphere. I enjoy walking around the lake, trying local food, and visiting small cafés. Compared with Ho Chi Minh City, it feels slower and gives me space to recharge mentally.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic012-q005', '{"sample_answer":"On my last holiday, I travelled to Da Lat with my family. We visited a lake, walked through pine-covered areas, tried local food, and spent time in several quiet cafés. The cool weather was a refreshing change from Ho Chi Minh City. I returned home feeling rested and mentally recharged.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic012-q006', '{"sample_answer":"I prefer spending holidays with my family or a few close friends. Familiar companions make planning easier and provide support if difficulties occur. We can share costs, photographs, and memorable experiences. I avoid very large groups because different expectations may create stress and reduce the flexibility that makes a holiday genuinely enjoyable.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic012-q007', '{"sample_answer":"I would enjoy an occasional holiday abroad because it provides direct exposure to different cultures, languages, and food. However, international travel is more expensive and requires careful planning. For shorter breaks, I prefer exploring Vietnam, which offers remarkable scenery and regional diversity without the same financial or administrative pressure.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic012-q008', '{"sample_answer":"My favourite means of transport is the train for long domestic journeys. It is slower than flying but offers more space, scenic views, and the freedom to move around. I can read or rest instead of concentrating on traffic. For everyday city travel, however, a motorbike remains more convenient.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic012-q009', '{"sample_answer":"People should use public transport more because it can reduce congestion, air pollution, and household travel costs. For this change to happen, services must be frequent, safe, clean, and well connected. Cities should also provide clear information and convenient payment, since environmental arguments alone will not persuade passengers to accept unreliable journeys.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic012-q010', '{"sample_answer":"For my next holiday, I would like to visit Da Nang and nearby Hoi An. The region offers beaches, historic architecture, and excellent local food. I would travel with my family for four or five days, allowing enough time to explore without rushing. The trip would provide both relaxation and cultural interest.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic012-q011', '{"sample_answer":"During holidays, many Vietnamese people visit relatives, travel to beaches or highland cities, and share meals with family. Major occasions such as Tet also involve cleaning homes, preparing traditional food, and giving good wishes. Younger people increasingly book short independent trips, but family connection remains an important part of holiday culture.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic012-q012', '{"sample_answer":"Holidays are important because they allow people to recover from work or study and spend uninterrupted time with family and friends. A change of environment can reduce stress and restore motivation. Holidays also create opportunities to explore culture and nature. Without regular breaks, long-term productivity and well-being may gradually decline.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic012-q013', '{"sample_answer":"The test centre is approximately eight kilometres from my home. I travelled here by motorbike because it was the most direct option and allowed me to control my arrival time. I left early to avoid heavy traffic and find the correct entrance. The journey took about thirty minutes and was generally smooth.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic013-q001', '{"sample_answer":"I try to eat healthy food most of the time by choosing vegetables, fruit, lean protein, and moderate portions of rice. I am not perfect, and I occasionally eat fast food when I am busy. However, planning simple meals and drinking enough water help me maintain better energy and concentration throughout the day.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic013-q002', '{"sample_answer":"At university, I usually eat a simple rice dish with vegetables and chicken or fish. If I have little time, I bring a homemade sandwich and some fruit. I avoid extremely heavy lunches because they make me sleepy in class. A balanced meal is affordable and helps me remain focused during the afternoon.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic013-q003', '{"sample_answer":"The unhealthiest food I can think of is heavily processed fried chicken served with chips and a sugary drink. It contains excessive salt, unhealthy fat, and calories while offering limited nutrition. Eating it occasionally is unlikely to cause serious harm, but consuming it regularly could contribute to obesity and other health problems.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic014-q001', '{"sample_answer":"I usually walk in the early evening, when the temperature is cooler and my work is finished. I choose a nearby park or a quiet street with enough lighting. A thirty-minute walk helps me clear my mind, review the day, and stay active without requiring expensive equipment or complicated preparation.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic014-q002', '{"sample_answer":"Walking is important because it is a simple form of exercise that most people can include in daily life. It improves cardiovascular health, reduces stress, and provides time away from screens. Regular walking can also support concentration and sleep. Even short journeys on foot become beneficial when they are done consistently.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic014-q003', '{"sample_answer":"At the moment, I exercise three or four times a week by walking, doing body-weight workouts, and occasionally playing badminton. I choose flexible activities because my university schedule changes. Regular exercise improves my concentration and reduces stress. My aim is consistency rather than intense training or competitive performance.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic014-q004', '{"sample_answer":"My favourite sport is badminton because it is fast, enjoyable, and accessible. It requires coordination, quick reactions, and strategic placement rather than only physical strength. I can play casually with friends or train more seriously when time allows. It also provides an effective workout without needing a large team or expensive equipment.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic014-q005', '{"sample_answer":"My favourite sports player is Cristiano Ronaldo because of his discipline, longevity, and determination to improve. Even after achieving exceptional success, he has maintained demanding training standards. I admire that professional attitude more than individual records. His career demonstrates how consistent preparation can extend natural ability and support performance under pressure.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic015-q001', '{"sample_answer":"A book I read recently was The Alchemist by Paulo Coelho. It follows a young shepherd searching for treasure and gradually learning about purpose, fear, and persistence. The language is accessible, but the story encourages reflection. I particularly liked the idea that pursuing a goal can transform a person, regardless of the final outcome.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic015-q002', '{"sample_answer":"I visit a library about once or twice a week, particularly when I need uninterrupted concentration. It provides a quiet environment, reliable resources, and fewer distractions than home. I usually review course materials, read reference books, or practise English there. The structured atmosphere encourages me to use my time more effectively.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic015-q003', '{"sample_answer":"In the library, I mainly study programming, review lecture notes, and read English materials. I sometimes borrow books or use academic databases for assignments. I keep my phone silent and choose a quiet desk, because the main advantage of the library is the opportunity to concentrate for a sustained period without interruption.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic015-q004', '{"sample_answer":"I think fewer people use traditional libraries regularly because digital books and online information are immediately accessible. However, libraries remain valuable for students, researchers, and anyone needing a quiet workspace. Modern libraries can stay relevant by offering digital resources, workshops, collaborative rooms, and knowledgeable staff rather than focusing only on printed books.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic015-q005', '{"sample_answer":"In the library, I mainly study programming, review lecture notes, and read English materials. I sometimes borrow books or use academic databases for assignments. I keep my phone silent and choose a quiet desk, because the main advantage of the library is the opportunity to concentrate for a sustained period without interruption.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic015-q006', '{"sample_answer":"When recommending a book, I first consider the person''s interests, reading level, and available time. I briefly explain the subject, describe what makes the book distinctive, and mention who might enjoy it. Rather than revealing the ending, I provide one appealing detail and, if possible, lend them my copy.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic015-q007', '{"sample_answer":"Yes, I regularly use a dictionary when learning English, especially when I encounter unfamiliar academic or technical vocabulary. I do not only check the Vietnamese meaning; I also examine pronunciation, example sentences, collocations, and word forms. This approach helps me understand how a word functions naturally rather than memorising an isolated translation.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic015-q008', '{"sample_answer":"I use a dictionary to check meaning, pronunciation, spelling, grammar, and common collocations. Example sentences are particularly useful because they show whether a word is formal and which prepositions it requires. I also compare several related words so that I can choose more accurately when speaking or writing in English.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic015-q009', '{"sample_answer":"I prefer electronic dictionaries because they are fast, portable, and frequently updated. They provide audio pronunciation, examples, and links between related words, which supports independent learning. Paper dictionaries can encourage careful browsing and reduce screen distraction, but they are less practical when I need an immediate answer during study.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic015-q010', '{"sample_answer":"A book I read recently was The Alchemist by Paulo Coelho. It follows a young shepherd searching for treasure and gradually learning about purpose, fear, and persistence. The language is accessible, but the story encourages reflection. I particularly liked the idea that pursuing a goal can transform a person, regardless of the final outcome.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic015-q011', '{"sample_answer":"I recently bought Clean Code by Robert C. Martin because I want to improve the clarity and maintainability of my programming. The book explains naming, functions, structure, and professional habits through practical examples. Some sections are demanding, but I expect it to support both personal projects and future software-development work.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic015-q012', '{"sample_answer":"I prefer buying books online because prices are easy to compare, reviews are available, and specialised titles are easier to find. However, a bookshop offers the pleasure of browsing and checking a book''s layout before purchasing. I therefore buy planned academic titles online but visit bookshops when I want inspiration.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic016-q001', '{"sample_answer":"Yes, I began learning English formally at secondary school, although the lessons focused mainly on grammar, vocabulary, and written exercises. That foundation was useful, but I had limited opportunities to speak. Later, I used videos, podcasts, and online conversations to develop more practical listening and communication skills.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic016-q002', '{"sample_answer":"English teaching at school is gradually becoming more practical. Many teachers now use videos, presentations, group discussions, and digital exercises instead of relying entirely on textbooks. However, large classes can still restrict speaking practice. Schools should provide frequent, low-pressure opportunities for students to communicate and receive individual feedback.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic016-q003', '{"sample_answer":"English learning for children has improved through interactive applications, online videos, better teacher training, and earlier exposure to authentic pronunciation. Students can now practise beyond the classroom and access materials suited to their level. The main challenge is helping them use technology purposefully rather than completing exercises without meaningful communication.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic016-q004', '{"sample_answer":"Yes, I use body language naturally when communicating, particularly through eye contact, facial expressions, and small hand movements. These signals help me show interest and clarify my attitude. I try to avoid exaggerated gestures because they may distract the listener. Appropriate body language makes spoken communication feel more confident and sincere.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic016-q005', '{"sample_answer":"I use body language most during presentations, interviews, and face-to-face conversations. Eye contact helps me connect with listeners, while gestures can emphasise a key point or explain size and direction. I am more careful in formal situations because posture and facial expression strongly influence the professional impression I create.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic016-q006', '{"sample_answer":"Body language supports communication by expressing emotion, reinforcing spoken meaning, and showing whether someone is engaged. It can make explanations clearer and help speakers appear confident. It is also useful when language ability is limited. However, gestures vary across cultures, so people should observe context and avoid making assumptions too quickly.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic016-q007', '{"sample_answer":"I currently study English as my main foreign language, and I have learned a small amount of Japanese through online materials. English is the priority because it supports my technology studies and career plans. Japanese interests me culturally, but I prefer improving one language consistently before attempting to reach a serious level in another.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic016-q008', '{"sample_answer":"I enjoy learning a foreign language because progress creates a strong sense of achievement and opens access to new people, ideas, and media. The process can be frustrating, especially when speaking, but regular practice gradually builds confidence. I particularly enjoy recognising expressions in films or using new vocabulary successfully in conversation.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic016-q009', '{"sample_answer":"Learning a foreign language is highly important in an increasingly connected world. It improves employment opportunities, supports international study and travel, and develops awareness of other cultures. It can also strengthen memory and communication skills. However, practical competence requires regular use rather than simply passing grammar examinations.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic016-q010', '{"sample_answer":"English is currently the most internationally useful language for technology, education, and business, so it is extremely important for my goals. However, calling it universally ''the most important'' ignores personal context. Someone''s local language, career, family, or destination may make Chinese, Japanese, Spanish, or another language more valuable.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic016-q011', '{"sample_answer":"The most difficult aspect of language study is speaking spontaneously. I may understand vocabulary and grammar but need extra time to organise ideas and pronounce them confidently. I address this by recording short answers, repeating useful phrases, and practising regularly. Consistency gradually reduces hesitation more effectively than occasional intensive study.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic016-q012', '{"sample_answer":"English was the first foreign language I learned. I began studying it formally at secondary school through vocabulary, grammar, and reading exercises. At first, I treated it mainly as an academic subject. Later, technology courses and international media showed me its practical value, which motivated me to improve listening and speaking.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic016-q013', '{"sample_answer":"I started learning English at secondary school in my hometown. Lessons took place in a traditional classroom and focused mostly on textbooks and written exercises. Although I gained a useful grammatical foundation, I had few opportunities for conversation. I later expanded my learning through online videos, podcasts, and independent speaking practice.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic016-q014', '{"sample_answer":"Regular exposure helped me most when learning English. I listened to short podcasts, read technology articles, and recorded myself answering common questions. Repeating useful phrases in context was more effective than memorising isolated word lists. Feedback from teachers also helped me notice pronunciation and grammar problems that I could not identify alone.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic017-q001', '{"sample_answer":"I enjoy documentaries, technology programmes, international news, and character-driven dramas. Informative programmes broaden my knowledge, while a good drama helps me relax and exposes me to natural English. I tend to avoid repetitive reality shows because I would rather spend limited screen time on content that is engaging or educational.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic017-q002', '{"sample_answer":"I watch television or streaming content for roughly one hour a day, usually after dinner. I prefer documentaries, news, and a well-written series rather than leaving the screen on continuously. Limiting my viewing time helps me relax without interfering with exercise, study, or sleep, which remain more important priorities.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic017-q003', '{"sample_answer":"I usually watch television alone because I can choose the programme, adjust subtitles, and pause when necessary. However, I prefer watching major football matches or comedies with family and friends because shared reactions make them more enjoyable. The best choice therefore depends on whether I want concentration or a social experience.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic017-q004', '{"sample_answer":"I like acoustic pop and instrumental music because both are easy to listen to without becoming overwhelming. Instrumental tracks help me concentrate while studying, whereas acoustic songs help me relax in the evening. I particularly appreciate music with a clear melody and meaningful lyrics rather than songs designed only to become briefly popular.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic017-q005', '{"sample_answer":"Pop music is probably the most popular genre in Vietnam, particularly among younger listeners. It is widely promoted through social media, streaming services, and television programmes. Catchy melodies and relatable lyrics make songs easy to share. Nevertheless, traditional, rap, and independent music also attract increasingly diverse audiences.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic017-q006', '{"sample_answer":"Listening to music can reduce stress, improve mood, and make routine tasks more enjoyable. It can also introduce listeners to different cultures and languages. However, loud music may damage hearing, and constant background music can reduce concentration. The benefits depend largely on volume, context, and personal listening habits.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic017-q007', '{"sample_answer":"Television can provide accessible education, reliable news, and affordable entertainment. Documentaries introduce complex subjects visually, while quality dramas expose viewers to different cultures and language. Watching programmes with family can also create shared discussion. Nevertheless, these benefits depend on selecting worthwhile content and maintaining reasonable screen-time habits.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic017-q008', '{"sample_answer":"My favourite film is The Pursuit of Happyness because it combines an emotional story with a realistic message about persistence. The main character faces financial hardship yet continues caring for his son and pursuing a career. The film is inspiring without suggesting that success is easy, and the performances make the struggle convincing.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic017-q009', '{"sample_answer":"My favourite singer is Sơn Tùng M-TP because his music combines memorable melodies with modern production. I also respect the way he developed a distinctive public image and reached a wide audience. Although I do not enjoy every release equally, several songs are energetic and strongly connected with contemporary Vietnamese pop culture.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic017-q010', '{"sample_answer":"I recently watched The Pursuit of Happyness, a drama about a father struggling with homelessness while training for a demanding career. The film was emotionally powerful because his professional ambition never replaced his responsibility to his son. It reminded me that resilience involves consistent action, not simply positive thinking.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic017-q011', '{"sample_answer":"My favourite actor is Leonardo DiCaprio because he chooses varied roles and gives convincing performances in complex films. I particularly admired his work in Inception, where the story required emotional restraint as well as intensity. His long career also shows a willingness to take creative risks rather than repeat one successful character.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic018-q001', '{"sample_answer":"I prefer cool, dry, and slightly sunny weather. It is comfortable enough for walking, studying, or travelling without feeling exhausted. Extremely hot days reduce my concentration, while prolonged rain can limit outdoor plans. Mild weather generally improves my energy and encourages me to spend more time outside rather than remain indoors.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic018-q002', '{"sample_answer":"Weather does affect my mood to some extent. Bright, mild days make me feel energetic and willing to go outside, whereas long periods of heavy rain can make me less motivated. Nevertheless, I try not to depend entirely on the weather and maintain useful routines, such as exercise and planned study.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic018-q003', '{"sample_answer":"When the weather is extremely hot, I stay indoors during the middle of the day and drink plenty of water. I wear light clothing, use a fan or air conditioning, and complete demanding tasks in the morning. If I exercise, I wait until evening to avoid heat exhaustion and unnecessary discomfort.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic019-q001', '{"sample_answer":"My favourite childhood game was hide-and-seek. I usually played it with neighbourhood friends after school, using trees and house entrances as hiding places. The game was exciting because it required quick decisions, observation, and teamwork. More importantly, it gave us an enjoyable reason to spend time outdoors together.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic019-q002', '{"sample_answer":"I most often played childhood games with neighbours and classmates who lived nearby. We met after school and organised games without adult supervision, provided we stayed close to home. Playing with the same group helped us understand one another, settle small disagreements, and build friendships that made childhood feel lively and secure.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic019-q003', '{"sample_answer":"Hide-and-seek required observation, patience, quick movement, and the ability to predict where other children might go. Communication was also useful when we played in teams. Although it seemed like simple entertainment, the game gradually developed confidence, cooperation, and problem-solving skills while keeping us physically active.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic019-q004', '{"sample_answer":"My favourite childhood game was hide-and-seek. I usually played it with neighbourhood friends after school, using trees and house entrances as hiding places. The game was exciting because it required quick decisions, observation, and teamwork. More importantly, it gave us an enjoyable reason to spend time outdoors together.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic020-q001', '{"sample_answer":"I prefer living in a quiet place because I need concentration for programming and English practice. A completely silent area might feel isolated, but constant traffic, construction, or loud music would be exhausting. Ideally, my home would be in a peaceful street with convenient access to shops and public transport.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic020-q002', '{"sample_answer":"Construction noise disturbs me most because it is repetitive, unpredictable, and difficult to ignore. Loud drilling can interrupt concentration even when windows are closed. I can tolerate ordinary traffic or conversations, but construction makes studying inefficient. When possible, I use headphones or move to a library until the work finishes.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic020-q003', '{"sample_answer":"Persistent noise can affect both physical and mental health. It may disrupt sleep, increase stress, and make concentration more difficult. Over time, very loud sound can also damage hearing. For these reasons, cities should enforce reasonable noise limits, while individuals can use quiet spaces and protective equipment when necessary.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic021-q001', '{"sample_answer":"My favourite photograph shows my family during a short trip to Da Lat. We are standing beside a lake with pine trees behind us, and everyone looks genuinely relaxed. The image is not professionally taken, but it captures a rare moment when our schedules allowed us to travel and enjoy time together.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic021-q002', '{"sample_answer":"The photograph was taken two years ago during a family holiday in Da Lat. We had just finished walking around the lake and stopped to admire the view. A passer-by kindly took the picture for us. The weather was cool, and everyone was smiling because the trip had gone particularly well.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic021-q003', '{"sample_answer":"The photograph is special because it preserves a peaceful family moment rather than a formal occasion. We were all free from work and study pressures and could simply enjoy one another''s company. Whenever I see it, I remember the cool weather, our conversations, and the importance of making time for family.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic022-q001', '{"sample_answer":"Blue is the colour I like most because it feels calm, reliable, and easy to combine with other colours. I often choose dark blue clothing for formal or everyday situations. It also reminds me of the sky and sea, so I associate it with openness, balance, and a more peaceful state of mind.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic022-q002', '{"sample_answer":"Colour is important when I choose clothes because it influences whether an outfit looks appropriate and coordinated. I normally select neutral shades such as white, black, or navy because they are versatile. I occasionally add a brighter colour, but comfort, fit, and the situation remain more important than following fashion trends.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic022-q003', '{"sample_answer":"Colour can affect my mood, although the effect is usually subtle. Soft blue or green makes a room feel calmer, while bright yellow can create a more energetic atmosphere. Dark colours sometimes feel serious or elegant. I therefore choose colours carefully in study spaces and clothing, especially on demanding days.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic023-q001', '{"sample_answer":"Yes, I have used several banking services in my local area, although I complete most routine tasks through a mobile application. I occasionally visit a branch to verify documents or solve a complicated issue. The staff have generally been helpful, but digital banking is considerably faster for transfers and bill payments.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic023-q002', '{"sample_answer":"I use banking services several times a week, mainly through my phone. I transfer money, pay bills, check transactions, and manage a small savings account. I rarely visit a physical branch because online services are available at any time. Nevertheless, branches remain important for identity checks and complex financial questions.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic023-q003', '{"sample_answer":"What I like most about modern banking services is convenience. Secure applications allow me to transfer money, pay bills, and monitor spending within minutes. Transaction records also help me manage my budget. However, banks must maintain strong security and accessible customer support because technical problems can affect people urgently.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic023-q004', '{"sample_answer":"I use a mid-range Android smartphone with a reliable battery and enough storage for study applications. It is not the newest model, but it performs everyday tasks efficiently. I prefer practical devices that offer good value because software, battery life, and security updates matter more to me than status or expensive design.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic023-q005', '{"sample_answer":"I use my phone for communication, maps, banking, calendars, English practice, and occasionally entertainment. It is particularly useful for checking schedules and accessing learning materials while travelling. However, I avoid completing serious programming work on it because a laptop provides a larger screen, better concentration, and more suitable development tools.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic023-q006', '{"sample_answer":"I should reduce unnecessary scrolling, especially before bed and during study breaks. Short social-media checks can easily become much longer than intended. I plan to disable non-essential notifications, set specific times for entertainment, and keep the phone away from my desk during focused work. These changes should improve concentration and sleep.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p1-topic024-q001', '{"sample_answer":"My favourite animal is the dog because dogs are loyal, intelligent, and emotionally responsive. A well-trained dog can provide companionship, encourage regular exercise, and even protect a home. I also admire their ability to build trust with people. However, owners must provide proper care, training, and long-term responsibility.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set001-q001', '{"sample_answer":"In this picture, I can see a lively group of friends sharing a meal at an outdoor restaurant. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.\n\n[Alternative Photo Description]: In this picture, I can see a smaller group having a more formal dinner indoors. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set001-q002', '{"sample_answer":"People like eating out with friends because it is relaxing and fun. They can enjoy good food, talk to each other, and forget about stress for a while. I think eating together helps people become closer. For this reason, I think it can have a positive effect on everyday life.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set001-q003', '{"sample_answer":"The last time I ate with my friends was at a small restaurant near my university. We ordered some simple but delicious food and talked about our studies and future plans. The feeling was relaxing, so I felt happy and comfortable. It wasn''t a special occasion, but we really enjoyed spending time together.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set002-q001', '{"sample_answer":"In this picture, I can see a cheerful family travelling by car, with the parents in front and children in the back. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set002-q002', '{"sample_answer":"The last time I travelled in a car was when I went to visit my relatives. The trip was quite comfortable because I could sit with my family and talk during the journey. We also listened to music and looked at the scenery, so the time passed quickly.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set002-q003', '{"sample_answer":"People can overcome the time of a long journey by preparing some activities before travelling. For example, they can listen to music, watch videos, read books, or talk with other passengers. Taking short breaks is also helpful because it makes the trip less tiring and more enjoyable. A clear plan and regular practice can make the situation much easier.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set003-q001', '{"sample_answer":"In this picture, I can see a smart television displaying streaming services while someone holds a remote. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.\n\n[Alternative Photo Description]: In this picture, I can see a woman relaxing on a sofa and using a remote control. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set003-q002', '{"sample_answer":"I often watch films or programmes at home, especially in the evening or on weekends. It helps me relax after studying or working for many hours. I usually watch short videos, movies, or educational programmes because they are both enjoyable and useful for improving my knowledge. For this reason, I think it can have a positive effect on everyday life.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set003-q003', '{"sample_answer":"I think both watching videos and reading are useful for learning, but they have different advantages. Videos are easier to understand because they include sound and images. However, reading helps people think more deeply and improve vocabulary. Personally, I prefer combining both methods to learn more effectively. This option suits me better, although other people may make a different choice.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set004-q001', '{"sample_answer":"In this picture, I can see a person watching television from a sofa. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.\n\n[Alternative Photo Description]: In this picture, I can see a man holding a remote and drinking coffee at home. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set004-q002', '{"sample_answer":"Yes, I sometimes watch TV, especially when I have free time in the evening. I usually watch news, films, or entertainment programmes. Watching TV helps me relax and learn about what is happening around the world, but I try not to spend too much time on it. Overall, I think this is a useful and positive experience.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set004-q003', '{"sample_answer":"Free time is important because it helps people relax and recover after a busy day. Without free time, people may feel tired and stressed. It also gives us a chance to do hobbies, spend time with family, and improve our mental health. For this reason, I think it can have a positive effect on everyday life.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set005-q001', '{"sample_answer":"In this picture, I can see a family lying on grass and smiling together. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.\n\n[Alternative Photo Description]: In this picture, I can see parents relaxing outdoors with their baby. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set005-q002', '{"sample_answer":"I usually read online articles, short stories, and materials related to my studies. I also enjoy reading English content because it helps me improve my vocabulary and grammar. Reading is a useful habit because it gives me new ideas and helps me learn more independently. Overall, I think this is a useful and positive experience.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set005-q003', '{"sample_answer":"Reading is important for children because it helps them develop imagination, vocabulary, and thinking skills. When children read regularly, they can learn new words and understand the world better. It also helps them become more patient and focused in their studies. For this reason, I think it can have a positive effect on everyday life.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set006-q001', '{"sample_answer":"In this picture, I can see a father carrying his child in a dramatic mountain landscape. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.\n\n[Alternative Photo Description]: In this picture, I can see a mother carrying her daughter through an autumn forest. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set006-q002', '{"sample_answer":"The last time I visited a new place was during a short trip with my family. We went to a peaceful area, tried local food, and took many photos. I felt excited because I could see something different from my daily life and spend quality time with my family.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set006-q003', '{"sample_answer":"People like to go to new places because travelling gives them fresh experiences and helps them relax. They can learn about different cultures, try local food, and meet new people. Visiting new places also helps people escape from stress and feel more motivated. For this reason, I think it can have a positive effect on everyday life.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set007-q001', '{"sample_answer":"In this picture, I can see two people cleaning a bright living room. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.\n\n[Alternative Photo Description]: In this picture, I can see two women tidying cushions and furniture. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set007-q002', '{"sample_answer":"The last time I did some physical work was when I cleaned my room and helped my family with housework. I swept the floor, arranged my desk, and moved some things. It was a little tiring, but I felt satisfied because the room became cleaner and more comfortable. Overall, the scene feels natural and engaging, and the people appear comfortable with what they are doing.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set007-q003', '{"sample_answer":"I do not think machines will do all our hard work in the future. Machines can help people save time and reduce physical effort, but humans are still needed to make decisions and solve problems. I believe machines will support us, not completely replace us. For this reason, I think it can have a positive effect on everyday life.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set008-q001', '{"sample_answer":"In this picture, I can see a presenter addressing colleagues in a modern meeting room. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set008-q002', '{"sample_answer":"The last time I gave a presentation was at university. I had to present a group project in front of my classmates and teacher. At first, I felt nervous, but I became more confident after speaking for a few minutes. In the end, I felt proud because I finished it well.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set008-q003', '{"sample_answer":"People are scared of public speaking because they worry about making mistakes or being judged by others. Some people also feel nervous when many people look at them. However, with enough preparation and practice, public speaking can become easier and less stressful. For this reason, I think it can have a positive effect on everyday life.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set009-q001', '{"sample_answer":"In this picture, I can see a woman standing on a boat near a coastal city. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.\n\n[Alternative Photo Description]: In this picture, I can see a woman relaxing on the deck of a sailing boat. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set009-q002', '{"sample_answer":"The last time I went to the sea was during a trip with my family. We walked along the beach, enjoyed seafood, and took many photos together. The weather was quite pleasant, and I felt relaxed because the sea view was peaceful and refreshing. I enjoyed the experience and would be happy to do something similar again.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set009-q003', '{"sample_answer":"Some people dislike going to the sea because it can be too hot, crowded, or noisy. Others may not enjoy swimming or may worry about safety. Also, travelling to the beach can sometimes be expensive, especially during holidays or peak seasons. For this reason, I think it can have a positive effect on everyday life.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set010-q001', '{"sample_answer":"In this picture, I can see a businessman checking his phone beside a train. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.\n\n[Alternative Photo Description]: In this picture, I can see a traveller waiting on an underground platform. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set010-q002', '{"sample_answer":"The last time I used public transport was when I took a bus to go around the city. It was cheaper than using a taxi, although it took more time. I think public transport is useful because it helps people save money and reduce traffic heavy traffic. I enjoyed the experience and would be happy to do something similar again.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set010-q003', '{"sample_answer":"We can increase the number of people using public transport by making it cleaner, safer, and more reliable. Tickets should be affordable, and buses or trains should arrive on time. If public transport becomes more convenient, more people will choose it instead of private vehicles. A clear plan and regular practice can make the situation much easier.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set011-q001', '{"sample_answer":"In this picture, I can see an audience laughing and watching a film in a cinema. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set011-q002', '{"sample_answer":"A time I laughed a lot was when I watched a comedy movie with my friends. The story was simple, but the actors were very funny. We laughed together throughout the film, and it helped me relax after a stressful week of studying. I enjoyed the experience and would be happy to do something similar again.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set011-q003', '{"sample_answer":"Yes, I think people from different countries may laugh at different things because humour is connected to culture, language, and daily life. However, some simple jokes, funny actions, and facial expressions can make almost everyone laugh, no matter where they come from. Overall, I think this is a useful and positive experience.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set012-q001', '{"sample_answer":"In this picture, I can see an adult teaching children to prepare food. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.\n\n[Alternative Photo Description]: In this picture, I can see children baking with another adult in a modern kitchen. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set012-q002', '{"sample_answer":"In my culture, many people learn to cook from their parents or grandparents at home. They often watch family members prepare meals and then practise simple dishes. Some people also learn from cooking videos online because they are easy to follow and very convenient. A clear plan and regular practice can make the situation much easier.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set012-q003', '{"sample_answer":"It is important for people to learn how to cook for themselves because it helps them live more independently. Cooking at home can also be healthier and cheaper than eating out every day. It is a useful life skill that everyone should have. For this reason, I think it can have a positive effect on everyday life.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set013-q001', '{"sample_answer":"In this picture, I can see a father helping a young child ride a bicycle in a park. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.\n\n[Alternative Photo Description]: In this picture, I can see an adult cycling beside a child on a quiet path. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set013-q002', '{"sample_answer":"Yes, in my country, most parents care a lot about their children. They usually support their children in schools, health, and daily life. Many parents work hard to give their children better opportunities and help them become responsible adults in the future. Overall, I think this is a useful and positive experience.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set013-q003', '{"sample_answer":"Parents care about their children because they love them and want them to have a good life. Children need guidance, protection, and emotional support when they grow up. Parents also want their children to become healthy, confident, and successful people. For this reason, I think it can have a positive effect on everyday life.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set014-q001', '{"sample_answer":"In this picture, I can see schoolchildren queuing beside a yellow school bus. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set014-q002', '{"sample_answer":"In my country, children go to school in different ways. Some walk or ride bicycles if they live nearby. Others go by motorbike with their parents, by bus, or by school bus. The way they travel often depends on distance and family conditions. A clear plan and regular practice can make the situation much easier.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set014-q003', '{"sample_answer":"In big cities, it is quite common for some students to live far from school because parents may choose better schools for them. However, in smaller towns or rural areas, many children usually study near their homes because it is more convenient. For this reason, I think it can have a positive effect on everyday life.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set015-q001', '{"sample_answer":"In this picture, I can see a performer demonstrating several energetic dance movements. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set015-q002', '{"sample_answer":"I like dancing, although I am not very good at it. Dancing is a fun way to relax, listen to music, and express emotions. I do not dance often, but I think it can make people feel more confident and energetic. For this reason, I think it can have a positive effect on everyday life.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set015-q003', '{"sample_answer":"In my country, people usually dance on special occasions such as weddings, festivals, school events, and music shows. Young people may also dance at parties or in clubs. Dancing makes the feeling more exciting and brings people closer together. Overall, I think this is a useful and positive experience.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set016-q001', '{"sample_answer":"In this picture, I can see children playing with hoops in a sunny park. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set016-q002', '{"sample_answer":"When I was a child, I often played hide-and-seek with my friends. We usually played near our houses after school. It was a simple game, but it was very exciting because everyone had to run, hide, and laugh together. I enjoyed the experience and would be happy to do something similar again.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set016-q003', '{"sample_answer":"Children''s games have changed a lot in the last 50 years. In the past, children often played outdoor games with friends. Nowadays, many children spend more time on phones, computers, and video games. Modern games are interesting, but outdoor games are still important for health and social skills.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set017-q001', '{"sample_answer":"In this picture, I can see a news presenter working among studio screens. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.\n\n[Alternative Photo Description]: In this picture, I can see a man reading a newspaper in front of a computer. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set017-q002', '{"sample_answer":"Most people in my country learn about world news through the internet, television, and social media. Young people often use smartphones to read news quickly, while older people may still prefer watching TV. Online news is popular because it is fast and convenient. A clear plan and regular practice can make the situation much easier.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set017-q003', '{"sample_answer":"The reporting of news has changed greatly in the last fifty years. In the past, people mainly got news from newspapers, radio, and television. Today, news is updated online every minute, and people can watch videos or read articles on their phones anytime. A clear plan and regular practice can make the situation much easier.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set018-q001', '{"sample_answer":"In this picture, I can see hikers crossing a rocky mountain ridge above the clouds. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.\n\n[Alternative Photo Description]: In this picture, I can see a group climbing through snowy conditions. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set018-q002', '{"sample_answer":"I would like to climb mountains, although I do not do it very often. I think mountain climbing is challenging but exciting. It allows people to enjoy fresh air, beautiful views, and a sense of achievement after reaching the top. Overall, I think this is a useful and positive experience.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set018-q003', '{"sample_answer":"Yes, I think outdoor activities are very important. They help people improve their physical health, reduce stress, and spend less time using electronic devices. Outdoor activities also give people a chance to enjoy nature and build stronger relationships with others. For this reason, I think it can have a positive effect on everyday life.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set019-q001', '{"sample_answer":"In this picture, I can see a mother reading while her child rests beside her. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set019-q002', '{"sample_answer":"It is important to play with children because it helps them feel loved and confident. Through playing, children can develop communication skills, creativity, and emotional connection with their parents. It also gives parents a chance to understand their children better. For this reason, I think it can have a positive effect on everyday life.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set019-q003', '{"sample_answer":"Parents should spend time with their children by doing simple but special activities. They can read books, play games, cook together, or talk about daily life. The most important thing is to give children attention and make them feel safe and supported. A clear plan and regular practice can make the situation much easier.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set020-q001', '{"sample_answer":"In this picture, I can see colleagues listening to a formal presentation. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.\n\n[Alternative Photo Description]: In this picture, I can see a young learner using a laptop with guidance from an adult. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set020-q002', '{"sample_answer":"The last time I gave a presentation was at university. I had to present a group project in front of my classmates and teacher. At first, I felt nervous, but I became more confident after speaking for a few minutes. In the end, I felt proud because I finished it well.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set020-q003', '{"sample_answer":"People are scared of public speaking because they worry about making mistakes or being judged by others. Some people also feel nervous when many people look at them. However, with enough preparation and practice, public speaking can become easier and less stressful. For this reason, I think it can have a positive effect on everyday life.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set021-q001', '{"sample_answer":"In this picture, I can see an adult supervising a child riding a horse. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set021-q002', '{"sample_answer":"One animal that I like is the dog. Dogs are friendly, loyal, and intelligent. They can make people feel less lonely and more relaxed. I also like dogs because they can protect the home and become close companions for family members. I enjoyed the experience and would be happy to do something similar again.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set021-q003', '{"sample_answer":"Animals are very important in our lives because they give people companionship and emotional support. Some animals also help humans with work, such as guide dogs or farm animals. Also, animals are part of nature, so we should protect and treat them kindly. For this reason, I think it can have a positive effect on everyday life.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set022-q001', '{"sample_answer":"In this picture, I can see a father and child playing football in a park. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.\n\n[Alternative Photo Description]: In this picture, I can see another parent encouraging a small child outdoors. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set022-q002', '{"sample_answer":"Outdoor activities have many benefits. They help people stay healthy, reduce stress, and improve their mood. They also give people a chance to enjoy fresh air and sunlight. For children, outdoor activities are especially useful because they help develop confidence and social skills. For this reason, I think it can have a positive effect on everyday life.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set022-q003', '{"sample_answer":"Many people like outdoor activities because they are enjoyable and refreshing. After spending many hours studying or working indoors, going outside can help people relax. Outdoor activities also allow people to meet others, enjoy nature, and live a more balanced lifestyle. For this reason, I think it can have a positive effect on everyday life.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set023-q001', '{"sample_answer":"In this picture, I can see parents helping their child prepare vegetables. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.\n\n[Alternative Photo Description]: In this picture, I can see a child carefully measuring ingredients while baking. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set023-q002', '{"sample_answer":"Yes, in my country, most parents care a lot about their children. They usually support their children in schools, health, and daily life. Many parents work hard to give their children better opportunities and help them become responsible adults in the future. Overall, I think this is a useful and positive experience.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set023-q003', '{"sample_answer":"Parents care about their children because they love them and want them to have a good life. Children need guidance, protection, and emotional support when they grow up. Parents also want their children to become healthy, confident, and successful people. For this reason, I think it can have a positive effect on everyday life.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set024-q001', '{"sample_answer":"In this picture, I can see a woman selecting products from a supermarket shelf. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set024-q002', '{"sample_answer":"The last time I shopped in a local store was a few days ago. I bought some snacks and daily items near my house. It was convenient because the store was close, and I could check the products directly before buying them. I enjoyed the experience and would be happy to do something similar again.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set024-q003', '{"sample_answer":"Nowadays, people like shopping online because it is convenient and saves time. They can compare prices, read reviews, and buy products without leaving home. Online shopping also offers many choices, although people should be careful about product quality and delivery time. For this reason, I think it can have a positive effect on everyday life.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set025-q001', '{"sample_answer":"In this picture, I can see a reporter interviewing a woman outdoors. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.\n\n[Alternative Photo Description]: In this picture, I can see another journalist speaking to a television camera. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set025-q002', '{"sample_answer":"I prefer watching news because it is faster and easier to understand. Videos can show images, interviews, and real situations, which make the news more interesting. However, I think newspapers are still useful when people want to read details more carefully. This option suits me better, although other people may make a different choice.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set025-q003', '{"sample_answer":"People need to watch the news because it helps them stay informed about important events in their country and around the world. News can also help people make better decisions in daily life, such as planning travel, understanding society, or preparing for changes. For this reason, I think it can have a positive effect on everyday life.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set026-q001', '{"sample_answer":"In this picture, I can see a busy crowd crossing a city street among tall buildings. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set026-q002', '{"sample_answer":"Living in a crowded city has both advantages and disadvantages. On the one hand, there are more jobs, schools, shops, and entertainment options. On the other hand, traffic, noise, and pollution can be stressful. Personally, I like city life, but I prefer quiet areas. Overall, I think this is a useful and positive experience.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set026-q003', '{"sample_answer":"Many people hate crowded places because they can feel noisy, stressful, and uncomfortable. It is difficult to move around, and people may feel less relaxed. Crowded places can also make people tired, especially after a long day of studying or working. For this reason, I think it can have a positive effect on everyday life.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set027-q001', '{"sample_answer":"In this picture, I can see passengers sitting quietly on a public bus. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set027-q002', '{"sample_answer":"The last time I went on vacation with someone else was a family trip. We visited a new place, tried local food, and took some photos together. I felt happy because I could relax and spend quality time with people I care about. I enjoyed the experience and would be happy to do something similar again.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set027-q003', '{"sample_answer":"Hanging out with other people has many benefits. It helps people relax, share their feelings, and build stronger relationships. It can also reduce loneliness and make life more enjoyable. Spending time with others is important for both mental health and social connection. For this reason, I think it can have a positive effect on everyday life.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set028-q001', '{"sample_answer":"In this picture, I can see a child surprising her mother with a wrapped gift. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set028-q002', '{"sample_answer":"A time I received a gift was on my birthday. My family gave me something simple but special, and I felt very happy. The gift was not expensive, but it showed that they cared about me and remembered my special day. I enjoyed the experience and would be happy to do something similar again.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set028-q003', '{"sample_answer":"In my country, people usually give gifts on birthdays, weddings, Tet holidays, graduations, and special celebrations. Gifts do not always have to be expensive. What matters most is the thought and care behind the gift. Overall, I think this is a useful and positive experience. Of course, the result depends on each person''s needs and situation.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set029-q001', '{"sample_answer":"In this picture, I can see an older man writing beside a laptop. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.\n\n[Alternative Photo Description]: In this picture, I can see another older man composing a handwritten letter at home. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set029-q002', '{"sample_answer":"Yes, I have written a handwritten letter before, but not very often. I think handwritten letters feel more personal than text messages. They take more time and effort, so they can show sincerity and care in a special way. Overall, I think this is a useful and positive experience.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set029-q003', '{"sample_answer":"I may write handwritten letters in the future on special occasions, such as birthdays or important celebrations. Although digital messages are faster and more convenient, handwritten letters can feel more special and memorable because they show personal effort. Overall, I think this is a useful and positive experience.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set030-q001', '{"sample_answer":"In this picture, I can see visitors discussing paintings in a bright gallery. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.\n\n[Alternative Photo Description]: In this picture, I can see people exploring a large contemporary museum. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set030-q002', '{"sample_answer":"Viewing artworks has many benefits. It helps people relax, think creatively, and understand different ideas or emotions. Art can also make people see life from another view. For students, viewing artworks may improve imagination and cultural awareness. For this reason, I think it can have a positive effect on everyday life.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set030-q003', '{"sample_answer":"People like to go to art exhibitions because they can enjoy beautiful works and learn about artists'' ideas. Exhibitions also give a quiet and inspiring feeling. Some people visit them to relax, while others go there to gain creativity and cultural knowledge. For this reason, I think it can have a positive effect on everyday life.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set031-q001', '{"sample_answer":"In this picture, I can see friends walking outdoors with shopping bags. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.\n\n[Alternative Photo Description]: In this picture, I can see three women smiling together inside a shopping centre. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set031-q002', '{"sample_answer":"The last time I went shopping was recently. I bought some clothes and personal items at a shopping mall. I did not buy many things, but I enjoyed looking around and comparing different products. It was a relaxing way to spend my free time. I enjoyed the experience and would be happy to do something similar again.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set031-q003', '{"sample_answer":"Some people dislike busy places because they can be noisy, crowded, and stressful. It may be difficult to move around or find what they need. Busy places can also make people feel tired, especially if they have to wait in long lines. For this reason, I think it can have a positive effect on everyday life.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set032-q001', '{"sample_answer":"In this picture, I can see a couple looking at clothes in a shop window. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set032-q002', '{"sample_answer":"The last time I went shopping was at a mall with my family. We bought some clothes and daily items. I enjoyed the experience because I could compare products directly and ask for opinions before making a decision. I enjoyed the experience and would be happy to do something similar again.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set032-q003', '{"sample_answer":"Many people enjoy shopping with friends because it is more fun and social than shopping alone. Friends can give useful advice and help choose better products. Shopping together also gives people a chance to talk, relax, and spend quality time. For this reason, I think it can have a positive effect on everyday life.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set033-q001', '{"sample_answer":"In this picture, I can see a father and son sharing breakfast. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.\n\n[Alternative Photo Description]: In this picture, I can see a grandfather and child eating together at home. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set033-q002', '{"sample_answer":"For breakfast, I usually eat something simple such as bread, eggs, noodles, or rice. I also like drinking milk or water in the morning. I do not always have a big breakfast, but I try to eat enough to have energy for the day. Overall, I think this is a useful and positive experience.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set033-q003', '{"sample_answer":"Yes, eating a good breakfast is important because it gives people energy after a long night of sleep. It can help students and workers focus better in the morning. A healthy breakfast also supports good health and prevents people from feeling too hungry later. For this reason, I think it can have a positive effect on everyday life.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set034-q001', '{"sample_answer":"In this picture, I can see a woman listening to music while resting on grass. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.\n\n[Alternative Photo Description]: In this picture, I can see a girl using headphones outdoors. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set034-q002', '{"sample_answer":"To relax, I usually listen to music, watch short videos, or take a short walk. Sometimes I also spend time with my family or drink coffee in a quiet place. These activities help me clear my mind and feel better after a busy day. Overall, I think this is a useful and positive experience.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set034-q003', '{"sample_answer":"It is important for people to relax because everyone needs time to recover from stress. If people work or study all the time, they may become tired and less productive. Relaxing helps improve mental health, energy, and focus. For this reason, I think it can have a positive effect on everyday life.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set035-q001', '{"sample_answer":"In this picture, I can see a child presenting flowers to his mother. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set035-q002', '{"sample_answer":"A time I gave flowers was on a special day for my mother. I bought a small bouquet to show my love and appreciation. It was not an expensive gift, but she was very happy, and I felt glad because I could make her smile. I enjoyed the experience and would be happy to do something similar again.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set035-q003', '{"sample_answer":"In my country, people often give flowers on birthdays, Women''s Day, Teachers'' Day, weddings, and graduation ceremonies. Flowers are popular because they are beautiful and special. They can express love, respect, congratulations, or gratitude in a simple way. Overall, I think this is a useful and positive experience.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set036-q001', '{"sample_answer":"In this picture, I can see an artist painting a colourful canvas. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.\n\n[Alternative Photo Description]: In this picture, I can see another painter working at an easel in a studio. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set036-q002', '{"sample_answer":"The last time I looked at some art was when I saw paintings online and in a public place. I spent time looking at the colours, details, and meanings behind the pictures. It was interesting because art can express emotions without using many words. Overall, the scene feels natural and engaging, and the people appear comfortable with what they are doing.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set036-q003', '{"sample_answer":"People enjoy creating art because it allows them to express feelings, ideas, and imagination. Art can also help people relax and reduce stress. Some people create art as a hobby, while others use it to share messages with society. For this reason, I think it can have a positive effect on everyday life.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set037-q001', '{"sample_answer":"In this picture, I can see a mother reading with her daughter. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.\n\n[Alternative Photo Description]: In this picture, I can see people talking together in an exhibition space. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set037-q002', '{"sample_answer":"It is important to play with children because it helps them feel loved and confident. Through playing, children can develop communication skills, creativity, and emotional connection with their parents. It also gives parents a chance to understand their children better. For this reason, I think it can have a positive effect on everyday life.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set037-q003', '{"sample_answer":"Parents should spend time with their children by doing simple but special activities. They can read books, play games, cook together, or talk about daily life. The most important thing is to give children attention and make them feel safe and supported. A clear plan and regular practice can make the situation much easier.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set038-q001', '{"sample_answer":"In this picture, I can see three professionals discussing documents in a meeting. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set038-q002', '{"sample_answer":"Yes, I like visiting exhibitions because they are interesting and educational. I can see creative works, learn new ideas, and understand different cultures. Even if I do not know much about art, exhibitions can still inspire me and help me think in new ways. Overall, I think this is a useful and positive experience.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set038-q003', '{"sample_answer":"Teachers should make exhibitions more interesting and easier to understand for young people. They can explain the background of artworks, organise group discussions, and ask students to share their opinions. They should also connect exhibitions with real life so students feel more engaged. Overall, I think this is a useful and positive experience.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set039-q001', '{"sample_answer":"In this picture, I can see a couple arranging framed pictures on a living-room wall. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set039-q002', '{"sample_answer":"Last year, I redecorated my bedroom because it felt dark and disorganised. I painted one wall a softer colour, moved the desk beside the window, added two framed photographs, and installed simple shelves for my books. The changes were inexpensive, but they created more space and natural light. I felt pleased because the room became both more practical for studying and more relaxing at night.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set039-q003', '{"sample_answer":"People decorate their homes with photographs or paintings because these objects make a space feel personal rather than purely functional. Family photographs preserve special memories, while artwork introduces colour, character, and sometimes culture. Carefully chosen images can also influence mood by making a room feel calmer or more inspiring.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set040-q001', '{"sample_answer":"In this picture, I can see a woman making a video call on her phone in a café. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set040-q002', '{"sample_answer":"A few months ago, I used my phone to contact my lecturer after a train delay threatened to make me miss an important presentation. I sent a concise message, attached evidence of the disruption, and joined the first part of the class by video call. Because I communicated promptly, my lecturer rearranged the order and I presented later.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set040-q003', '{"sample_answer":"Many people spend a great deal of time on their phones because one device gives communication, entertainment, navigation, banking, study materials, and work tools. Social media and short videos are deliberately designed to hold attention, so users can lose track of time. Phones are extremely practical, but constant notifications can reduce focus and sleep quality.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set041-q001', '{"sample_answer":"In this picture, I can see parents and their child cycling together through a park. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set041-q002', '{"sample_answer":"Families enjoy cycling together because it combines exercise, conversation, and exploration without requiring expensive equipment or complicated planning. Adults can model healthy habits, while children gradually develop balance, confidence, and road awareness. Cycling also allows family members to share a goal and notice their neighbourhood from a different view.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set041-q003', '{"sample_answer":"Children should spend more time outdoors because active play supports physical fitness, teamwork, curiosity, and emotional health and happiness. Natural environments also encourage imagination and teamwork in ways that screens cannot always give. However, adults should choose safe places, give suitable equipment, and balance structured sport with free play.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set042-q001', '{"sample_answer":"In this picture, I can see two people movement a framed picture while rearranging their living room. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set042-q002', '{"sample_answer":"Yes, I enjoy decorating my home because small design changes can make everyday life more comfortable and organised. I prefer simple improvements such as warm lighting, plants, framed photographs, and practical storage rather than expensive furniture. Planning the colours and layout is also a creative break from work.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set042-q003', '{"sample_answer":"Before rearranging a room, people should consider its main purpose, available space, natural light, and how occupants move through it. Large furniture must not block doors, windows, electrical sockets, or emergency routes. It is also sensible to measure items, set a realistic budget, and discuss changes with everyone who uses the room.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set043-q001', '{"sample_answer":"In this picture, I can see an adult helping a child ride a horse near a stable. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set043-q002', '{"sample_answer":"I especially enjoy being around dogs because they are expressive, sociable, and usually responsive to people. I feel relaxed when walking or playing with a well-trained dog, although I always approach new animals carefully and respect the owner''s instructions. Horses are also fascinating because they are powerful yet sensitive.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set043-q003', '{"sample_answer":"Animals are useful to humans in many ways. Some give companionship and emotional support, while others assist with farming, transport, rescue work, security, and therapy. Wildlife also maintains ecosystems through pollination, seed dispersal, and population control. However, usefulness should not justify cruelty or exploitation. For this reason, I think it can have a positive effect on everyday life.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set044-q001', '{"sample_answer":"In this picture, I can see a journalist conducting an outdoor television interview in a city. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set044-q002', '{"sample_answer":"I prefer getting news from television and trusted online broadcasts because visual reports give quick context and are easier to follow during major events. Printed newspapers, however, often offer deeper thinking and fewer things that break focus. My ideal approach is to watch a concise report first and then read a reliable article to verify details.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set044-q003', '{"sample_answer":"Keeping up with current events helps people understand decisions that may affect their work, schools, finances, safety, and community. Reliable news also helps citizens to participate in informed discussions and recognise misinformation. However, following every update can become stressful, so people should choose trustworthy sources and limit constant notifications. A balanced news routine supports responsible decision-making without allowing negative headlines to dominate one''s attention.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set045-q001', '{"sample_answer":"In this picture, I can see two hikers walking along a peaceful forest path. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set045-q002', '{"sample_answer":"Some people enjoy walking in a forest because the quiet surroundings, fresh air, and natural scenery give relief from traffic, screens, and daily pressure. Uneven paths also make walking physically engaging without feeling like formal exercise. Forests encourage careful watching, reflection, and a slower pace. Provided visitors follow marked routes and protect the environment, a woodland walk can improve mood, focus, and appreciation of nature.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set045-q003', '{"sample_answer":"People should spend more time in nature because regular contact with green spaces can reduce stress, encourage exercise, and restore focus. It also helps children and adults understand why environmental protection matters. This does not require expensive travel. local parks, riversides, and community gardens can give similar benefits.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set046-q001', '{"sample_answer":"In this picture, I can see an adult and children preparing food together in a kitchen. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set046-q002', '{"sample_answer":"Last Tet, I cooked spring rolls with my parents and younger sister. We divided the tasks: my father prepared the vegetables, my mother seasoned the filling, and my sister and I wrapped everything carefully. Although the kitchen became rather untidy, we talked, laughed, and solved small problems together.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set046-q003', '{"sample_answer":"Cooking together can strengthen relationships because people communicate, divide duties, and work towards a shared result. The relaxed setting often encourages conversations that might not happen during a formal meeting. Family recipes can also preserve cultural traditions and allow older relatives to pass on practical knowledge. For this reason, I think it can have a positive effect on everyday life.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set047-q001', '{"sample_answer":"In this picture, I can see a family getting into a car before a journey. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set047-q002', '{"sample_answer":"My most memorable car journey was a family trip to Da Lat last summer. We left before sunrise, crossed several winding mountain roads, and stopped at a quiet viewpoint for breakfast. Heavy rain slowed us down, but we listened to music and talked throughout the trip. When the weather cleared, the scenery was spectacular.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set047-q003', '{"sample_answer":"Travelling by car offers privacy, flexible departure times, convenient luggage space, and the freedom to stop along the route. It is especially practical for families or places with limited public transport. However, long drives can be tiring, traffic and parking create stress, and fuel costs may be considerable.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set048-q001', '{"sample_answer":"In this picture, I can see friends talking over drinks at an outdoor café. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set048-q002', '{"sample_answer":"Last weekend, I visited a small riverside café with two close friends. We ordered Vietnamese coffee and shared a light dessert while discussing our studies and future plans. The café was quiet enough for conversation, but still had a lively feeling. We stayed for nearly two hours and left feeling refreshed.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set048-q003', '{"sample_answer":"Cafés are popular meeting places because they give comfortable seating, refreshments, and a neutral feeling where people can talk without the formality of a workplace or the effort of hosting at home. Many cafés also offer Wi-Fi and flexible opening hours, making them suitable for study or informal meetings. Their popularity depends on balancing lively social energy with enough privacy and reasonable prices.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set049-q001', '{"sample_answer":"In this picture, I can see two people collaborating on drawings and craft materials. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set049-q002', '{"sample_answer":"During a community workshop, I created a large poster with three classmates. We first exchanged ideas, selected a simple environmental theme, and divided the drawing, lettering, and colouring tasks according to our strengths. We occasionally disagreed about the design, but careful discussion produced a much stronger result. I enjoyed the experience and would be happy to do something similar again.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set049-q003', '{"sample_answer":"Drawing and making art help children express ideas that they may not yet be able to explain verbally. Creative tasks develop fine motor skills, careful watching, patience, and problem-solving, while open-ended materials encourage imagination rather than a single correct answer. Group art can also teach sharing and useful feedback.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set050-q001', '{"sample_answer":"In this picture, I can see a long queue of passengers waiting at a ticket office. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set050-q002', '{"sample_answer":"Last month, I waited in a long queue at a railway station because several ticket machines had stopped working. At first, the situation was frustrating, especially because passengers received little information. I used the time to check my travel documents and read the news on my phone. Staff in the end opened another counter, and I caught my train.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set050-q003', '{"sample_answer":"Stations, banks, and hospitals can reduce waiting time by offering online appointments, digital tickets, self-service machines, and clear real-time information. Staffing levels should reflect predictable busy periods, while simple cases can be handled at express counters. Well-designed queues and accurate estimates also reduce frustration even when delays are unavoidable.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set051-q001', '{"sample_answer":"In this picture, I can see two young children building a tall tower with colourful blocks. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set051-q002', '{"sample_answer":"As a child, I enjoyed building with colourful blocks and playing hide-and-seek with neighbours. Construction toys allowed me to invent houses and vehicles, while outdoor games gave me exercise and taught me to cooperate with others. We rarely needed expensive equipment because the rules were simple and flexible.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set051-q003', '{"sample_answer":"Play is very important for young children because it is one of the main ways they explore ideas, practise language, and understand social rules. Physical games develop teamwork, while imaginative play strengthens creativity and emotional awareness. Playing with others teaches negotiation, patience, and conflict resolution. For this reason, I think it can have a positive effect on everyday life.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set052-q001', '{"sample_answer":"In this picture, I can see a group of students studying together around a laptop and books. The setting looks clear and natural. The people seem focused on what they are doing, and their body language looks relaxed. I can also see some useful details in the background. Overall, it looks like a normal and positive moment that many people can understand.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set052-q002', '{"sample_answer":"I prefer combining both methods, although I study alone when I need deep focus. Independent study lets me control the pace and focus on weak areas, while a group is valuable for discussing difficult concepts and testing ideas. For an important subject, I would prepare individually first and then meet reliable classmates.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p2-set052-q003', '{"sample_answer":"Studying with other people can improve learning because students explain concepts in different ways, notice one another''s mistakes, and share useful resources. A committed group also creates accountability and makes demanding tasks feel less isolating. However, sessions need a clear goal, time limit, and division of topics. otherwise, conversation becomes distracting. When managed well, collaborative study deepens understanding and develops communication skills alongside academic knowledge.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set001-q001', '{"sample_answer":"In the first picture, two people are travelling by car, and the man is driving while the woman is sitting beside him. In the second picture, several passengers are sitting together on a train and talking. Both pictures show comfortable ways of travelling, but the car looks more private, while the train looks more social and relaxing.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set001-q002', '{"sample_answer":"Travelling by car is convenient because people can choose their own route, stop whenever they want, and carry more luggage. Travelling by train is also useful because passengers do not have to drive, so they can read, sleep, or talk during the journey. Both options can be comfortable, depending on the distance and the purpose of the trip.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set001-q003', '{"sample_answer":"Some people like to travel by train because it is less stressful than driving. They can enjoy the scenery, move around a little, and avoid traffic jams. Train travel is also better for long distances because passengers can rest instead of concentrating on the road. For many people, it feels safe, affordable, and better for the environment.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set002-q001', '{"sample_answer":"In the first picture, two children are playing chess together at a table. In the second picture, two children are playing video games at home. Both activities look enjoyable, but chess seems quieter and more good for thinking skills, while video games look more exciting and entertaining. The pictures show two different ways for children to spend their free time.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set002-q002', '{"sample_answer":"I prefer playing chess because it helps me think carefully and plan ahead. Chess may be slower than video games, but it improves focus, patience, and problem-solving skills. Video games can be fun and relaxing, especially with friends, but if people play too much, they may waste time. For learning and mental training, chess is more useful to me.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set002-q003', '{"sample_answer":"Yes, outdoor activities are very important because they help people stay healthy and reduce stress. Many children now spend a lot of time indoors with screens, so playing outside gives them fresh air, movement, and time with other people. Outdoor activities also help children become more confident because they can explore, cooperate, and learn from real experiences.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set003-q001', '{"sample_answer":"The first picture shows a pine forest with many tall trees and a peaceful natural feeling. The second picture shows a beautiful beach with palm trees, blue water, and bright sunshine. Both places look attractive, but they create different feelings. The forest seems quiet and refreshing, while the beach looks warm, open, and cheerful.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set003-q002', '{"sample_answer":"I would choose the pine forest because I prefer quiet places where I can walk slowly and enjoy fresh air. A beach is beautiful and fun, but it can be hot and crowded, especially during holidays. A forest feels calmer and more suitable for relaxing, taking photos, and escaping from city noise for a while.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set003-q003', '{"sample_answer":"Yes, I think weather affects human emotions quite strongly. Sunny weather often makes people feel more energetic and positive, while heavy rain or dark skies can make some people feel tired or less motivated. However, it depends on the person and the situation. For example, rain may feel unpleasant outside, but relaxing when people are safe at home.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set004-q001', '{"sample_answer":"In the first picture, two football players are competing on a field during a match. In the second picture, an athlete is doing the high jump in a stadium. The first sport is a team sport that needs teamwork, while the second is an individual sport that requires personal technique, speed, and body control. Both look intense and competitive.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set004-q002', '{"sample_answer":"The main difference is that football depends heavily on teamwork, strategy, and communication between players. High jump, on the other hand, focuses more on individual performance, physical strength, and technique. In football, success comes from the whole team working together. In high jump, the athlete must rely mainly on their own preparation and focus.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set004-q003', '{"sample_answer":"Some sports are considered more important because they are more popular, easier to watch, or connected to national pride. For example, football is important in many countries because it attracts large audiences and brings people together. Other sports may be less famous, but they are still valuable because they develop discipline, health, and personal success.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set005-q001', '{"sample_answer":"In the first picture, some students are studying together in a library with books around them. In the second picture, a person is studying alone in a coffee shop. Both places can be useful for learning, but the library looks more academic and quiet, while the coffee shop seems more casual, comfortable, and flexible.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set005-q002', '{"sample_answer":"I prefer studying in a library when I need deep focus because it is usually quiet and has many useful resources. However, I also like coffee shops for lighter tasks, such as reviewing notes or reading. The feeling in a coffee shop can feel more relaxed, but it may also be noisy. So my choice depends on what I need to study.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set005-q003', '{"sample_answer":"Studying in a library can be difficult because there may be strict rules, limited space, or pressure to stay completely silent. Coffee shops have different problems: they can be noisy, crowded, and distracting. Some people may also spend too much money on drinks. Both places are useful, but students need to choose the right environment for each task.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set006-q001', '{"sample_answer":"The first picture shows a family sitting together outside their house. They look happy and comfortable. The second picture shows a young woman standing alone on a balcony, probably in an apartment. The two pictures contrast family life with independent living. One suggests warmth and support, while the other suggests freedom, privacy, and personal independence.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set006-q002', '{"sample_answer":"At this stage of my life, I prefer living with my family because it gives me emotional support and a sense of security. I can share daily life with people who care about me, and it is also more affordable. Living alone may offer more freedom, but it can sometimes feel lonely and stressful, especially when facing problems.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set006-q003', '{"sample_answer":"Many people like to live alone nowadays because they want independence and privacy. They can organise their own schedule, decorate their space, and make decisions without disturbing others. In modern life, people also move to different cities for work or study. Living alone can be challenging, but it helps many people become more responsible.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set007-q001', '{"sample_answer":"The first picture shows a family sitting together outside their house. They look happy and comfortable. The second picture shows a young woman standing alone on a balcony, probably in an apartment. The two pictures contrast family life with independent living. One suggests warmth and support, while the other suggests freedom, privacy, and personal independence.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set007-q002', '{"sample_answer":"At this stage of my life, I prefer living with my family because it gives me emotional support and a sense of security. I can share daily life with people who care about me, and it is also more affordable. Living alone may offer more freedom, but it can sometimes feel lonely and stressful, especially when facing problems.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set007-q003', '{"sample_answer":"Many people like to live alone nowadays because they want independence and privacy. They can organise their own schedule, decorate their space, and make decisions without disturbing others. In modern life, people also move to different cities for work or study. Living alone can be challenging, but it helps many people become more responsible.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set008-q001', '{"sample_answer":"The first picture shows a person riding a camel in a desert. The second picture shows people travelling in a horse-drawn carriage. Both pictures show animals being used for transportation, but in different environments. The camel is useful in dry desert areas, while the horse carriage looks more like a traditional or tourist activity in a city.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set008-q002', '{"sample_answer":"The interesting point is that both methods connect travel with culture and history. Riding a camel can give people a special desert experience, while travelling by horse carriage can feel traditional and romantic. These ways of travelling are slower than modern vehicles, but they allow people to enjoy the journey itself rather than only focusing on speed.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set008-q003', '{"sample_answer":"I think animals should not be treated simply as machines for transportation. They can be used in some traditional or tourist activities, but their health and comfort must come first. People should make sure the animals are not overworked or treated badly. If the activity causes suffering, it should be limited or replaced by safer options.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set009-q001', '{"sample_answer":"In the first picture, an adult and a child are interacting with a white horse outside. In the second picture, several children are sitting indoors and learning, possibly through toys or classroom activities. The pictures show two ways children can learn about the world: through direct contact with animals and through indoor educational activities.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set009-q002', '{"sample_answer":"Yes, I like interacting with animals because it can be relaxing and special. Animals often make people feel calmer, and they teach us patience and kindness. For example, feeding or touching a horse can be a memorable experience, especially for children. However, people should always follow safety rules and treat animals gently and respectfully.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set009-q003', '{"sample_answer":"Yes, children should learn about animals because it helps them understand nature and develop empathy. When children learn how animals live, eat, and behave, they become more responsible and respectful. This knowledge is also useful for environmental schools. If children grow up caring about animals, they may be more willing to protect nature in the future.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set010-q001', '{"sample_answer":"In the first picture, an adult and a child are interacting with a white horse outside. In the second picture, several children are sitting indoors and learning, possibly through toys or classroom activities. The pictures show two ways children can learn about the world: through direct contact with animals and through indoor educational activities.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set010-q002', '{"sample_answer":"Yes, I like interacting with animals because it can be relaxing and special. Animals often make people feel calmer, and they teach us patience and kindness. For example, feeding or touching a horse can be a memorable experience, especially for children. However, people should always follow safety rules and treat animals gently and respectfully.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set010-q003', '{"sample_answer":"Yes, children should learn about animals because it helps them understand nature and develop empathy. When children learn how animals live, eat, and behave, they become more responsible and respectful. This knowledge is also useful for environmental schools. If children grow up caring about animals, they may be more willing to protect nature in the future.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set011-q001', '{"sample_answer":"The first picture shows a man cycling alone on a road. The second picture shows a team of people rowing together on the water. Both are physical sports, but cycling in this picture looks more individual, while rowing clearly requires teamwork. They both need strength, endurance, and regular practice to perform well. Overall, the scene feels natural and engaging, and the people appear comfortable with what they are doing.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set011-q002', '{"sample_answer":"Cycling can be difficult because it requires strong legs, balance, and the ability to stay focused on the road for a long time. Rowing is also challenging because the team must move together at the same rhythm. If one person loses timing, the whole boat can be affected. Both sports require discipline and fitness.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set011-q003', '{"sample_answer":"Many people prefer team sports because they enjoy teamwork and social connection. In a team, players can support each other, share pressure, and celebrate success together. Team sports also help people improve communication and responsibility. Individual sports are good for self-discipline, but team sports often feel more enjoyable because people do not face challenges alone.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set012-q001', '{"sample_answer":"The first picture shows a person walking in a quiet pine forest. The second picture shows people riding camels across a desert with large sand dunes. These places are very different. The forest looks cool, green, and peaceful, while the desert looks hot, dry, and open. Both places show natural beauty in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set012-q002', '{"sample_answer":"People who live in forests may be used to a quiet lifestyle and may work with farming, tourism, or forest protection. People in desert areas often need to adapt to a hotter climate and limited water. They may depend on traditional transport, local tourism, or special knowledge of the environment. Living in both places requires adaptation.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set012-q003', '{"sample_answer":"I would rather visit the pine forest because I prefer cool weather and green scenery. It would be a good place for walking, taking photos, and relaxing away from the city. The desert is impressive and unique, but it might be too hot and hard on the body for me. A forest feels more comfortable and peaceful.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set013-q001', '{"sample_answer":"In the first picture, athletes are playing wheelchair basketball indoors. In the second picture, two older people are playing tennis outdoors. Both pictures show that sport can be enjoyed by different people in different conditions. One activity takes place inside and seems fast and competitive, while the other is outside and looks more relaxed and social.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set013-q002', '{"sample_answer":"Indoor sports are useful because people can play them in a controlled environment, without worrying too much about weather. They are suitable for organised training and competitions. Outdoor sports, however, give fresh air, sunlight, and a stronger connection with nature. Both types improve physical health, confidence, and time with other people in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set013-q003', '{"sample_answer":"I do not think the main purpose of playing a game is only to win. Winning can be motivating, especially in competitions, but games also teach teamwork, discipline, fairness, and emotional control. For many people, the real value of sport is improving themselves, staying healthy, and enjoying time with others, not just getting first place.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set014-q001', '{"sample_answer":"The first picture shows a family shopping in a modern supermarket. The second picture shows vendors and fresh products in a traditional market. Both places are used for buying daily goods, but they have different atmospheres. The supermarket looks clean, organised, and convenient, while the market looks lively, colourful, and more local. Overall, the scene feels natural and engaging, and the people appear comfortable with what they are doing.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set014-q002', '{"sample_answer":"Supermarkets are convenient because products are arranged clearly, prices are usually fixed, and people can buy many things in one place. Traditional markets are also beneficial because they often offer fresh food, local products, and a more personal shopping experience. Markets can support small sellers, while supermarkets save time and feel more comfortable for many customers.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set014-q003', '{"sample_answer":"Many people do not like shopping because it can be tiring, crowded, and time-consuming. Some people feel stressed when they have to compare prices or choose between too many products. Others dislike waiting in lines or dealing with traffic around shopping areas. Nowadays, online shopping is popular partly because it reduces these problems.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set015-q001', '{"sample_answer":"The first picture shows people hiking on a mountain, while the second picture shows a family walking on a sunny beach. Both places are outdoor destinations, but they offer different experiences. The mountain looks adventurous and physically challenging, while the beach looks more relaxed and family-friendly. Both can help people enjoy nature and escape from daily stress.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set015-q002', '{"sample_answer":"I would like to go to the beach because it feels more relaxing and easier to enjoy with family or friends. I can walk, take photos, swim, or simply sit near the water. Hiking is also interesting, but it requires more energy and preparation. For a short holiday, the beach would be more comfortable for me.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set015-q003', '{"sample_answer":"Mountain activities are suitable for people who enjoy challenges, exercise, and adventure. They are good for young people or anyone who is physically active. Beach activities are suitable for families, children, and people who want to relax. Older people may also prefer the beach if the place is safe and not too crowded.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set016-q001', '{"sample_answer":"In the first picture, a child is learning to play the piano at home with adults nearby. In the second picture, musicians are performing on a stage in front of an audience. The two pictures show private and public ways of playing music. One looks personal and educational, while the other looks energetic, social, and professional.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set016-q002', '{"sample_answer":"I like playing music at home because it feels more comfortable and less stressful. At home, people can practise slowly, make mistakes, and improve without pressure. However, playing music on a stage can be exciting because performers can share their emotions with an audience. For beginners, I think home is the best place to start.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set016-q003', '{"sample_answer":"Playing music in different places can create very different emotions. At home, music often feels calm, personal, and relaxing. In a concert or public performance, it can feel powerful, exciting, and inspiring because people share the experience together. The place changes not only the sound, but also the confidence and emotions of the performer.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set017-q001', '{"sample_answer":"The first picture shows a very crowded beach with many people and colourful umbrellas. The second picture shows two people sitting quietly near a lake with a mountain in the background. These places create opposite feelings. The crowded beach looks energetic but noisy, while the lake looks peaceful, natural, and suitable for quiet relaxation.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set017-q002', '{"sample_answer":"I do not really like going to crowded beaches because they can be noisy and stressful. It is difficult to find a quiet place, and people may feel less comfortable when there are too many visitors. I prefer beaches when they are not too busy, because then I can enjoy the sea, take photos, and relax properly.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set017-q003', '{"sample_answer":"Many people like quiet places because they help reduce stress and clear the mind. After studying or working for many hours, people often need a calm environment to recover their energy. Quiet places also allow people to think deeply, talk comfortably, or enjoy nature without things that break focus. That is why they are important for mental health.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set018-q001', '{"sample_answer":"The first picture shows a traveller standing at an airport and looking at a plane. The second picture shows a person waiting for a train on a platform. Both pictures are about long-distance travel, but flying looks faster and more modern, while train travel seems calmer and more connected to the ground. Overall, the scene feels natural and engaging, and the people appear comfortable with what they are doing.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set018-q002', '{"sample_answer":"Many people prefer going by plane rather than by train because flying is much faster, especially for long distances or international trips. It can save a lot of time and make business or family travel more convenient. Planes also connect places that trains cannot reach easily. For people with limited time, speed is the biggest advantage of flying.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set018-q003', '{"sample_answer":"Flying makes many people uncomfortable for several reasons. Some are afraid of heights or accidents, while others feel nervous during take-off and landing. Airports can also be stressful because of security checks, delays, and crowded waiting areas. Also, sitting in a small seat for a long time can be tiring, especially on long flights.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set019-q001', '{"sample_answer":"The first picture shows a woman picking vegetables, possibly tomatoes, in a garden. The second picture shows an adult and a child watering plants together. Both pictures show gardening as a practical and peaceful activity. It can involve growing food, taking care of flowers, and spending time outdoors with family members. Overall, the scene feels natural and engaging, and the people appear comfortable with what they are doing.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set019-q002', '{"sample_answer":"Growing a garden has many benefits because it helps people relax, stay active, and spend time in nature. If people grow vegetables, they can also have fresh and healthy food at home. Gardening teaches patience because plants need time and care to grow. It can also make the living space greener and more pleasant.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set019-q003', '{"sample_answer":"Growing vegetables and flowers is appealing because it gives people a sense of achievement. When they see something grow because of their own effort, they feel satisfied. Vegetables are useful for daily meals, while flowers make a place more beautiful. Gardening can also become a special family activity, especially when adults and children do it together.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set020-q001', '{"sample_answer":"In the first picture, a woman is listening to music with headphones at home. In the second picture, a singer is performing with a band. The first way of enjoying music is private and relaxing, while the second is public and energetic. Both pictures show that music can be enjoyed alone or with other people.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set020-q002', '{"sample_answer":"There are many ways to enjoy music. People can listen to songs with headphones when they want privacy, or they can attend concerts to experience live performances. Listening alone is good for relaxing and focusing on personal feelings. Watching live music is more exciting because the audience can feel the energy of the performers and the crowd.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set020-q003', '{"sample_answer":"Listening to music has many benefits. It can reduce stress, improve mood, and help people feel more energetic. Some people use music to focus while studying, while others use it to relax after a busy day. Music can also connect people because songs often express emotions that many people share. For this reason, I think it can have a positive effect on everyday life.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set021-q001', '{"sample_answer":"The first picture shows a family playing chess together at home. The second picture shows a boy playing a video game with a controller. Both are indoor activities, but they develop different skills. Chess looks calm and based on planning, while video games look more exciting and fast-paced. Both can be enjoyable if people use their time wisely.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set021-q002', '{"sample_answer":"I prefer playing chess because it trains patience, focus, and logical thinking. It may not be as exciting as video games, but it helps people plan carefully and make better decisions. Video games can be fun and improve reactions, but they can also become hard to stop. For me, chess is more useful and special as a mental activity.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set021-q003', '{"sample_answer":"Yes, indoor activities are important because people cannot always go outside, especially in bad weather or in busy cities. Indoor activities such as reading, chess, music, or simple games help people relax and learn new skills. They are also useful for family time because people can spend time together at home in a safe environment.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set022-q001', '{"sample_answer":"In the first picture, a father and child are cooking together at home. In the second picture, a man is eating outside at a restaurant or cafe. The two pictures show different places to enjoy food. Cooking at home looks warm and family-oriented, while eating out looks convenient, social, and relaxing. Overall, the scene feels natural and engaging, and the people appear comfortable with what they are doing.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set022-q002', '{"sample_answer":"It is appealing to eat at different places because each place gives a different experience. Eating at home can feel comfortable and healthy because people can choose the ingredients. Eating at a restaurant is more convenient and allows people to try new dishes. Food is not only about taste. it is also connected to feeling, relationships, and special memories.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set022-q003', '{"sample_answer":"On special occasions, people often like to eat at restaurants, hotels, or family homes. Restaurants are popular for birthdays and celebrations because they save time and offer a pleasant feeling. However, some families prefer eating at home during traditional holidays because it feels warmer and more personal. The best place depends on the occasion and the people involved.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set023-q001', '{"sample_answer":"The first picture shows a family sitting together outside a house, while the second picture shows a young woman standing alone on a balcony. These pictures compare family living with independent living. The family scene feels warm, safe, and helpful, while the woman alone suggests privacy, freedom, and personal independence. Overall, the scene feels natural and engaging, and the people appear comfortable with what they are doing.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set023-q002', '{"sample_answer":"At this stage of my life, I prefer living with my family because it gives me emotional support and a sense of security. I can share daily life with people who care about me, and it is also more affordable. Living alone may offer more freedom, but it can sometimes feel lonely and stressful, especially when facing problems.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set023-q003', '{"sample_answer":"Many people like to live alone nowadays because they want independence and privacy. They can organise their own schedule, decorate their space, and make decisions without disturbing others. In modern life, people also move to different cities for work or study. Living alone can be challenging, but it helps many people become more responsible.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set024-q001', '{"sample_answer":"The first picture shows a cyclist riding alone on a road. The second picture shows a group of people rowing together on rough water. Both sports are demanding, but they require different skills. Cycling seems more individual and focused on endurance, while rowing is clearly a team activity that depends on rhythm, teamwork, and teamwork.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set024-q002', '{"sample_answer":"Cycling can be difficult because it requires strong legs, balance, and the ability to stay focused on the road for a long time. Rowing is also challenging because the team must move together at the same rhythm. If one person loses timing, the whole boat can be affected. Both sports require discipline and fitness.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set024-q003', '{"sample_answer":"Some people prefer team sports because they enjoy sharing the experience with others. Team sports create motivation, communication, and a sense of belonging. When people train or compete together, they can support each other and share responsibility. Individual sports are good for personal discipline, but team sports often feel more encouraging and enjoyable.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set025-q001', '{"sample_answer":"The first picture shows two people travelling with luggage, probably at an airport or station. The second picture shows a person travelling in the mountains with a backpack. These pictures compare a more comfortable, organised way of travelling with a more adventurous style. One looks convenient and planned, while the other looks independent and exploratory.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set025-q002', '{"sample_answer":"I think both ways of travelling are interesting. Travelling with luggage through airports or stations is suitable for family holidays or business trips because it is organised and comfortable. Backpacking in the mountains is more adventurous and flexible, but it requires more energy and preparation. Personally, I like a balanced trip that is safe but still gives me new experiences.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set025-q003', '{"sample_answer":"The first way is convenient because people can carry more things and follow a clear travel plan, but it may be expensive and sometimes stressful because of delays. The second way gives people freedom and a close connection with nature, but it can be tiring and less comfortable. Both ways have advantages, depending on the traveller’s personality and purpose.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set026-q001', '{"sample_answer":"The first picture shows people getting on a public bus, while the second picture shows a man standing beside a red private car. These two vehicles represent very different travel experiences. A bus is shared, affordable, and practical for many passengers, while a private car looks more comfortable, personal, and flexible. Overall, the scene feels natural and engaging, and the people appear comfortable with what they are doing.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set026-q002', '{"sample_answer":"Travelling by bus is usually cheaper and better for the environment because many people share one vehicle. However, it can be crowded and slower because passengers must follow fixed routes and schedules. Travelling by private car is more comfortable because people can choose when to leave and where to stop, but it is more expensive and can add to traffic problems.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set026-q003', '{"sample_answer":"People still choose to have their own cars because cars give freedom, privacy, and convenience. A car is useful for families, emergencies, and trips to places where public transport is limited. Although owning a car costs money for fuel, parking, and maintenance, many people feel it gives them better control over their daily travel.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set027-q001', '{"sample_answer":"The first picture shows young people playing a quiet board game outdoors, while the second shows a child playing a fast-paced video game indoors. Both pictures show everyday activities, but the places are different. The first scene looks more personal, while the second shows another way to do a similar activity. Overall, they show that people can have similar experiences in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set027-q002', '{"sample_answer":"I prefer playing chess because it helps me think carefully and plan ahead. Chess may be slower than video games, but it improves focus, patience, and problem-solving skills. Video games can be fun and relaxing, especially with friends, but if people play too much, they may waste time. For learning and mental training, chess is more useful to me.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set027-q003', '{"sample_answer":"Outdoor activities are important because they counter sedentary routines, improve physical fitness, and give people a mental break from screens and enclosed spaces. They also encourage careful watching, confidence, and time with other people. The exact activity should match a person''s age, health, and local environment. even a daily walk can be worth doing.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set028-q001', '{"sample_answer":"The first picture shows a traveller looking towards an aircraft through a large window, while the second shows a passenger waiting beside a train. Both pictures show everyday activities, but the places are different. The first scene looks more personal, while the second shows another way to do a similar activity. Overall, they show that people can have similar experiences in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set028-q002', '{"sample_answer":"Plane travel is considerably faster over long distances and can connect countries directly, while trains usually give more space, easier boarding, and better views along the route. Flying may involve security queues, baggage limits, and higher emissions, while rail travel can be slow or unavailable in some regions. This option suits me better, although other people may make a different choice.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set028-q003', '{"sample_answer":"Flying makes many people uncomfortable for several reasons. Some are afraid of heights or accidents, while others feel nervous during take-off and landing. Airports can also be stressful because of security checks, delays, and crowded waiting areas. Also, sitting in a small seat for a long time can be tiring, especially on long flights.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set029-q001', '{"sample_answer":"The first picture shows footballers competing on a field, while the second shows an athlete performing the high jump. Both pictures show everyday activities, but the places are different. The first scene looks more personal, while the second shows another way to do a similar activity. Overall, they show that people can have similar experiences in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set029-q002', '{"sample_answer":"The main difference is that football depends heavily on teamwork, strategy, and communication between players. High jump, on the other hand, focuses more on individual performance, physical strength, and technique. In football, success comes from the whole team working together. In high jump, the athlete must rely mainly on their own preparation and focus.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set029-q003', '{"sample_answer":"Some sports are considered more important because they are more popular, easier to watch, or connected to national pride. For example, football is important in many countries because it attracts large audiences and brings people together. Other sports may be less famous, but they are still valuable because they develop discipline, health, and personal success.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set030-q001', '{"sample_answer":"The first picture shows a gardener harvesting ripe vegetables, while the second shows two people tending plants together. Both pictures show everyday activities, but the places are different. The first scene looks more personal, while the second shows another way to do a similar activity. Overall, they show that people can have similar experiences in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set030-q002', '{"sample_answer":"Growing a garden gives gentle exercise, reduces stress, and gives people direct contact with seasonal change. Vegetables can supply fresh food and help families understand where meals come from, while flowers add colour and support insects. Gardening is appealing because progress is visible and personally rewarding. Although it requires patience, water, and regular care, even a small balcony garden can create a special sense of achievement.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set030-q003', '{"sample_answer":"Growing a garden gives gentle exercise, reduces stress, and gives people direct contact with seasonal change. Vegetables can supply fresh food and help families understand where meals come from, while flowers add colour and support insects. Gardening is appealing because progress is visible and personally rewarding. Although it requires patience, water, and regular care, even a small balcony garden can create a special sense of achievement.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set031-q001', '{"sample_answer":"The first picture shows a family preparing for a car journey, while the second shows passengers travelling by train. Both pictures show everyday activities, but the places are different. The first scene looks more personal, while the second shows another way to do a similar activity. Overall, they show that people can have similar experiences in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set031-q002', '{"sample_answer":"Travelling by car is convenient because people can choose their own route, stop whenever they want, and carry more luggage. Travelling by train is also useful because passengers do not have to drive, so they can read, sleep, or talk during the journey. Both options can be comfortable, depending on the distance and the purpose of the trip.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set031-q003', '{"sample_answer":"Some people like to travel by train because it is less stressful than driving. They can enjoy the scenery, move around a little, and avoid traffic jams. Train travel is also better for long distances because passengers can rest instead of concentrating on the road. For many people, it feels safe, affordable, and better for the environment.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set032-q001', '{"sample_answer":"The first picture shows people boarding a public bus, while the second shows a man standing beside a private sports car. Both pictures show everyday activities, but the places are different. The first scene looks more personal, while the second shows another way to do a similar activity. Overall, they show that people can have similar experiences in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set032-q002', '{"sample_answer":"Travelling by bus is usually cheaper and better for the environment because many people share one vehicle. However, it can be crowded and slower because passengers must follow fixed routes and schedules. Travelling by private car is more comfortable because people can choose when to leave and where to stop, but it is more expensive and can add to traffic problems.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set032-q003', '{"sample_answer":"People still choose to have their own cars because cars give freedom, privacy, and convenience. A car is useful for families, emergencies, and trips to places where public transport is limited. Although owning a car costs money for fuel, parking, and maintenance, many people feel it gives them better control over their daily travel.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set033-q001', '{"sample_answer":"The first picture shows hikers crossing a snowy mountain, while the second shows a family strolling along a sunny beach. Both pictures show everyday activities, but the places are different. The first scene looks more personal, while the second shows another way to do a similar activity. Overall, they show that people can have similar experiences in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set033-q002', '{"sample_answer":"I would choose the place that offers natural scenery, easy to manage weather, and opportunities for both activity and rest. Personally, I prefer the quieter option because it allows me to walk, take photographs, and recover from city pressure without feeling rushed. However, safety, transport, cost, and the needs of companions are decisive.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set033-q003', '{"sample_answer":"Mountain activities are suitable for people who enjoy challenges, exercise, and adventure. They are good for young people or anyone who is physically active. Beach activities are suitable for families, children, and people who want to relax. Older people may also prefer the beach if the place is safe and not too crowded.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set034-q001', '{"sample_answer":"The first picture shows a person riding a camel in a desert, while the second shows tourists travelling in a horse-drawn carriage. Both pictures show everyday activities, but the places are different. The first scene looks more personal, while the second shows another way to do a similar activity. Overall, they show that people can have similar experiences in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set034-q002', '{"sample_answer":"Both forms of travel are slow, traditional and closely connected to the local place. Riding a camel lets people experience the desert, while a horse-drawn carriage is better for city streets. Neither is ideal for a long journey, but both can be memorable because travellers can enjoy the view and learn about local culture.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set034-q003', '{"sample_answer":"Animals should only be used for transport when their welfare is protected, the load is suitable, and humane options are really unavailable. Traditional practices may have cultural value, but tourism can lead to overwork, poor equipment, and inadequate rest. Strict standards, veterinary care, and limited working hours are very important. Where modern vehicles are practical, people should avoid treating animals as machines and choose more ethical forms of travel.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set035-q001', '{"sample_answer":"The first picture shows a woman listening privately through headphones, while the second shows a singer performing live on stage. Both pictures show everyday activities, but the places are different. The first scene looks more personal, while the second shows another way to do a similar activity. Overall, they show that people can have similar experiences in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set035-q002', '{"sample_answer":"Music can be enjoyed privately through headphones, shared informally at home, or experienced collectively at a live performance. Listening alone offers control, convenience, and quiet reflection, while concerts create energy through the audience and direct connection with performers. Neither method is universally better. I use headphones for focus and relaxation, but choose live music when I want a memorable social experience and can manage the cost and noise.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set035-q003', '{"sample_answer":"Listening to music can regulate mood, reduce stress, and make repeated tasks more enjoyable. It may also support focus when the style matches the activity, and shared musical tastes often help people connect socially. However, loud volume can damage hearing and lyrics may distract from demanding work. Used thoughtfully, music becomes an accessible tool for relaxation, emotional expression, cultural learning, and motivation.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set036-q001', '{"sample_answer":"The first picture shows an individual cyclist on a country road, while the second shows a coordinated rowing team on the water. Both pictures show everyday activities, but the places are different. The first scene looks more personal, while the second shows another way to do a similar activity. Overall, they show that people can have similar experiences in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set036-q002', '{"sample_answer":"Cycling can be difficult because it requires strong legs, balance, and the ability to stay focused on the road for a long time. Rowing is also challenging because the team must move together at the same rhythm. If one person loses timing, the whole boat can be affected. Both sports require discipline and fitness.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set036-q003', '{"sample_answer":"Some people prefer team sports because they enjoy sharing the experience with others. Team sports create motivation, communication, and a sense of belonging. When people train or compete together, they can support each other and share responsibility. Individual sports are good for personal discipline, but team sports often feel more encouraging and enjoyable.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set037-q001', '{"sample_answer":"The first picture shows students working in a formal library, while the second shows a learner studying in a relaxed outdoor or café setting. Both pictures show everyday activities, but the places are different. The first scene looks more personal, while the second shows another way to do a similar activity. Overall, they show that people can have similar experiences in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set037-q002', '{"sample_answer":"I prefer studying in a library when I need deep focus because it is usually quiet and has many useful resources. However, I also like coffee shops for lighter tasks, such as reviewing notes or reading. The feeling in a coffee shop can feel more relaxed, but it may also be noisy. So my choice depends on what I need to study.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set037-q003', '{"sample_answer":"Libraries can feel overly quiet, have limited opening hours, and restrict conversation, while popular cafés may be noisy, crowded, and dependent on buying food or drinks. Internet quality and seating comfort also vary. Students should match the environment to the task, use headphones when suitable, and set a clear study goal. No location automatically guarantees focus. disciplined habits remain more important than feeling alone.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set038-q001', '{"sample_answer":"The first picture shows a person walking through a pine forest, while the second shows a tropical beach with palm trees. Both pictures show everyday activities, but the places are different. The first scene looks more personal, while the second shows another way to do a similar activity. Overall, they show that people can have similar experiences in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set038-q002', '{"sample_answer":"I would choose the pine forest because I prefer quiet places where I can walk slowly and enjoy fresh air. A beach is beautiful and fun, but it can be hot and crowded, especially during holidays. A forest feels calmer and more suitable for relaxing, taking photos, and escaping from city noise for a while.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set038-q003', '{"sample_answer":"Yes, I think weather affects human emotions quite strongly. Sunny weather often makes people feel more energetic and positive, while heavy rain or dark skies can make some people feel tired or less motivated. However, it depends on the person and the situation. For example, rain may feel unpleasant outside, but relaxing when people are safe at home.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set039-q001', '{"sample_answer":"The first picture shows employees attending an indoor presentation, while the second shows people taking a break and walking outdoors. Both pictures show everyday activities, but the places are different. The first scene looks more personal, while the second shows another way to do a similar activity. Overall, they show that people can have similar experiences in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set039-q002', '{"sample_answer":"Office work offers stable equipment, shelter, and easier communication, while outdoor work gives movement, fresh air, and variety. Many people prefer offices because weather is predictable and digital tasks are easier to organise. However, prolonged sitting can harm health and reduce contact with nature. The best arrangement would include ergonomic places and equipment, regular outdoor breaks, and occasional flexible work when duties allow.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set039-q003', '{"sample_answer":"Outdoor activities are important because they counter sedentary routines, improve physical fitness, and give people a mental break from screens and enclosed spaces. They also encourage careful watching, confidence, and time with other people. The exact activity should match a person''s age, health, and local environment. even a daily walk can be worth doing.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set040-q001', '{"sample_answer":"The first picture shows people working on a farm, while the second shows employees collaborating in a modern office. Both pictures show everyday activities, but the places are different. The first scene looks more personal, while the second shows another way to do a similar activity. Overall, they show that people can have similar experiences in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set040-q002', '{"sample_answer":"Farm work is physical, seasonal, and closely connected to weather, animals, or crops, while office work usually involves computers, meetings, and fixed steps. Farming can offer independence and tangible results but also brings financial uncertainty and demanding hours. Offices give stable places and equipment and teamwork, although routines may feel sedentary. The better choice depends on skills, health, preferred lifestyle, and tolerance for risk.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set040-q003', '{"sample_answer":"Some people enjoy farm life because it is quieter and closer to nature. They may like caring for animals, growing food and seeing clear results from their work. Farm work can be tiring and the weather can cause problems, but many people prefer the open space and slower way of life.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set041-q001', '{"sample_answer":"The first picture shows a person organising photographs or research at home, while the second shows a worker caring for dairy cattle. Both pictures show everyday activities, but the places are different. The first scene looks more personal, while the second shows another way to do a similar activity. Overall, they show that people can have similar experiences in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set041-q002', '{"sample_answer":"I visited a dairy farm during a school trip several years ago. We watched workers feed the cattle, clean the equipment, and explain how milk was stored safely before transportation. The scale of the operation surprised me, especially the attention required every day. The visit was memorable because it connected an ordinary supermarket product with animal care, hygiene, technology, and the demanding work of farmers.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set041-q003', '{"sample_answer":"Dairy farms supply milk and related products that many people use for healthy diets and making food. They also support rural jobs, transport, animal care services, and local businesses. However, their importance creates duties: farms must keep everything clean, protect animal health, deal with waste, and reduce environmental damage. Consumers and governments should encourage open and honest, lasting production rather than valuing low prices above health and fair standards.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set042-q001', '{"sample_answer":"The first picture shows a family moving through an airport with luggage, while the second shows travellers waiting at a railway station. Both pictures show everyday activities, but the places are different. The first scene looks more personal, while the second shows another way to do a similar activity. Overall, they show that people can have similar experiences in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set042-q002', '{"sample_answer":"Plane travel is considerably faster over long distances and can connect countries directly, while trains usually give more space, easier boarding, and better views along the route. Flying may involve security queues, baggage limits, and higher emissions, while rail travel can be slow or unavailable in some regions. Overall, I think this is a useful and positive experience.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set042-q003', '{"sample_answer":"I think travelling by train is often better for families. Parents do not have to drive, children can move around a little, and everyone can rest or talk together. Trains also have more space and toilets. However, a car may be better when the family has a lot of luggage or visits a remote place.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set043-q001', '{"sample_answer":"The first picture shows a bright green city park in summer, while the second shows a city street covered by winter snow. Both pictures show everyday activities, but the places are different. The first scene looks more personal, while the second shows another way to do a similar activity. Overall, they show that people can have similar experiences in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set043-q002', '{"sample_answer":"A city in summer is usually brighter, greener, and more active outdoors, but heat, crowds, and higher prices can be uncomfortable. In winter, streets may feel quieter and visually striking, although snow can disrupt transport and shorten daylight. I would visit in early summer because attractions remain accessible and outdoor events are plentiful, provided the temperature is moderate and accommodation is booked in advance.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set043-q003', '{"sample_answer":"I would visit the city in early summer because the days are longer and most outdoor places are open. Walking, sightseeing and public events are also easier in warm weather. Winter can look beautiful, especially when it snows, but cold weather may cause transport problems and make outdoor activities less comfortable.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set044-q001', '{"sample_answer":"The first picture shows a snowy mountain range, while the second shows a dry desert crossed by camels. Both pictures show everyday activities, but the places are different. The first scene looks more personal, while the second shows another way to do a similar activity. Overall, they show that people can have similar experiences in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set044-q002', '{"sample_answer":"A snowy mountain is cold, steep, and potentially slippery, while a desert is hot, dry, and exposed to strong sunlight. Both environments are beautiful but hard on the body, requiring specialised clothing, water, navigation, and emergency planning. I would prefer the mountain because I enjoy cooler air and dramatic scenery, although I would only travel with an experienced guide and check the weather carefully.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set044-q003', '{"sample_answer":"I would choose the place that offers natural scenery, easy to manage weather, and opportunities for both activity and rest. Personally, I prefer the quieter option because it allows me to walk, take photographs, and recover from city pressure without feeling rushed. However, safety, transport, cost, and the needs of companions are decisive.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set045-q001', '{"sample_answer":"The first picture shows a volunteer helping an older person use technology, while the second shows volunteers planting and caring for trees. Both pictures show everyday activities, but the places are different. The first scene looks more personal, while the second shows another way to do a similar activity. Overall, they show that people can have similar experiences in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set045-q002', '{"sample_answer":"Helping an older person with technology creates an quick personal connection and develops patience, while environmental volunteering produces a visible benefit for the wider community. Both require reliability and respectful communication. I would choose tree planting because I enjoy practical outdoor work and the results can last for years. However, volunteering should respond to genuine local needs rather than simply providing attractive photographs for people.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set045-q003', '{"sample_answer":"Helping an older person with technology creates an quick personal connection and develops patience, while environmental volunteering produces a visible benefit for the wider community. Both require reliability and respectful communication. I would choose tree planting because I enjoy practical outdoor work and the results can last for years. However, volunteering should respond to genuine local needs rather than simply providing attractive photographs for people.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set046-q001', '{"sample_answer":"The first picture shows children playing football outdoors, while the second shows two children concentrating on a mobile phone. Both pictures show everyday activities, but the places are different. The first scene looks more personal, while the second shows another way to do a similar activity. Overall, they show that people can have similar experiences in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set046-q002', '{"sample_answer":"Outdoor play develops movement, teamwork, and contact with the physical world, while a phone gives entertainment, information, and communication in a compact form. For children, outdoor play should normally take priority because it supports health and social confidence. Phones still have educational value, but adults should set age-suitable limits, choose suitable content, and avoid allowing screens to replace sleep, exercise, or face-to-face relationships.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set046-q003', '{"sample_answer":"Outdoor play develops movement, teamwork, and contact with the physical world, while a phone gives entertainment, information, and communication in a compact form. For children, outdoor play should normally take priority because it supports health and social confidence. Phones still have educational value, but adults should set age-suitable limits, choose suitable content, and avoid allowing screens to replace sleep, exercise, or face-to-face relationships.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set047-q001', '{"sample_answer":"The first picture shows a colourful traditional market, while the second shows a customer shopping in a modern supermarket. Both pictures show everyday activities, but the places are different. The first scene looks more personal, while the second shows another way to do a similar activity. Overall, they show that people can have similar experiences in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set047-q002', '{"sample_answer":"Traditional markets offer fresh local produce, direct contact with sellers, and a lively cultural feeling, while supermarkets give fixed prices, clear organisation, and convenient one-stop shopping. I prefer supermarkets for packaged goods and reliable hygiene, but visit markets for seasonal fruit and vegetables. The ideal choice depends on product quality, distance, budget, and whether the customer values efficiency or a more personal experience.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set047-q003', '{"sample_answer":"Traditional markets offer fresh local produce, direct contact with sellers, and a lively cultural feeling, while supermarkets give fixed prices, clear organisation, and convenient one-stop shopping. I prefer supermarkets for packaged goods and reliable hygiene, but visit markets for seasonal fruit and vegetables. The ideal choice depends on product quality, distance, budget, and whether the customer values efficiency or a more personal experience.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set048-q001', '{"sample_answer":"The first picture shows a family eating a home-cooked meal, while the second shows friends dining together in a restaurant. Both pictures show everyday activities, but the places are different. The first scene looks more personal, while the second shows another way to do a similar activity. Overall, they show that people can have similar experiences in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set048-q002', '{"sample_answer":"Eating at home is usually cheaper, healthier, and more private because people control ingredients and portion sizes. Restaurants offer convenience, variety, and a special social feeling, although cost and healthy quality can vary. I prefer home meals on ordinary days and restaurants for celebrations or new cuisine. This balance allows me to protect my budget while still enjoying the cultural and social experience of eating out.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set048-q003', '{"sample_answer":"Eating at home is usually cheaper, healthier, and more private because people control ingredients and portion sizes. Restaurants offer convenience, variety, and a special social feeling, although cost and healthy quality can vary. I prefer home meals on ordinary days and restaurants for celebrations or new cuisine. This balance allows me to protect my budget while still enjoying the cultural and social experience of eating out.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set049-q001', '{"sample_answer":"The first picture shows people relaxing on a beach, while the second shows climbers tackling a snowy mountain. Both pictures show everyday activities, but the places are different. The first scene looks more personal, while the second shows another way to do a similar activity. Overall, they show that people can have similar experiences in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set049-q002', '{"sample_answer":"Compare going to the beach and climbing a mountain. The first option generally offers a more direct and traditional experience, while the second tends to give greater convenience, flexibility, or independence. Their how suitable it is depends on cost, safety, time, easy access, and the needs of the people involved. Overall, I think this is a useful and positive experience.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set049-q003', '{"sample_answer":"I would choose the beach because I enjoy swimming, walking by the sea and relaxing in warm weather. It also suits people of different ages and needs less special equipment. Mountain climbing is exciting and offers beautiful views, but it requires better fitness, careful planning and good weather, so it is not suitable for everyone.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set050-q001', '{"sample_answer":"The first picture shows a student learning through a laptop, while the second shows a child reading a printed book in a library. Both images are connected with digital and printed learning, although the settings and feeling are clearly different. The first scene looks more personal, while the second shows another way to do a similar activity. Overall, they show that people can have similar experiences in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set050-q002', '{"sample_answer":"Some people prefer printed books because they are comfortable to read and have fewer distractions. Others choose laptops because they can quickly search for information, watch lessons and carry many digital books. The better choice depends on the task. Books are good for deep reading, while laptops are useful for research and online study.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set050-q003', '{"sample_answer":"I think using both methods is most effective. Printed books help me focus and remember ideas, while a laptop gives quick access to videos, online exercises and recent information. I usually read the main topic in a book first and then use a laptop to check examples or practise what I have learned.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set051-q001', '{"sample_answer":"The first picture shows a crowded commercial city centre, while the second shows a farmer working alone in an open field. Both pictures show everyday activities, but the places are different. The first scene looks more personal, while the second shows another way to do a similar activity. Overall, they show that people can have similar experiences in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set051-q002', '{"sample_answer":"A crowded city offers jobs, schools, entertainment, and good services, but it can also create noise, expensive housing, heavy traffic, and constant pressure. A farm gives space, nature, and a slower routine, although transport and career options may be limited. I would live in a well-connected smaller city, because it offers very important opportunities without the very large crowds of a major big city.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set051-q003', '{"sample_answer":"I would prefer to live in a smaller city because it offers more jobs, schools, hospitals and public transport. At the same time, it is usually quieter and less crowded than a major city. Farm life is peaceful and close to nature, but it may be too far from services and career opportunities for me.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set052-q001', '{"sample_answer":"The first picture shows a woman taking a selfie, while the second shows travellers photographing a natural landscape. Both pictures show everyday activities, but the places are different. The first scene looks more personal, while the second shows another way to do a similar activity. Overall, they show that people can have similar experiences in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set052-q002', '{"sample_answer":"Selfies record personal identity and social occasions, while landscape photographs focus on place, feeling, and careful watching. I consider landscape images more special when they capture a rare environment or tell a story beyond the photographer. However, a careful selfie with family can preserve an equally valuable memory. Meaning depends less on the category than on intention, composition, and the experience connected with the image.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set052-q003', '{"sample_answer":"Selfies record personal identity and social occasions, while landscape photographs focus on place, feeling, and careful watching. I consider landscape images more special when they capture a rare environment or tell a story beyond the photographer. However, a careful selfie with family can preserve an equally valuable memory. Meaning depends less on the category than on intention, composition, and the experience connected with the image.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set053-q001', '{"sample_answer":"The first picture shows customers browsing jewellery in a shopping centre, while the second shows a shopper choosing clothes in a local market. Both pictures show everyday activities, but the places are different. The first scene looks more personal, while the second shows another way to do a similar activity. Overall, they show that people can have similar experiences in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set053-q002', '{"sample_answer":"I prefer local markets because the food is often fresh, prices can be reasonable and customers can speak directly with sellers. They also have a lively local feeling. Shopping malls are cleaner and more convenient in bad weather, but they can be expensive. I choose the place depending on what I need to buy.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set053-q003', '{"sample_answer":"Buying an expensive item can be reasonable when it is durable, ethically produced, and used frequently. However, purchasing luxury goods mainly for status may create debt, waste, and short-lived satisfaction. I prefer comparing quality, repairability, and cost per use before deciding. People should distinguish genuine value from advertising pressure and avoid judging others by possessions, since financial security and special experiences often give greater long-term health and happiness.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set054-q001', '{"sample_answer":"The first picture shows children playing football as a team, while the second shows an athlete competing alone in the high jump. Both pictures show everyday activities, but the places are different. The first scene looks more personal, while the second shows another way to do a similar activity. Overall, they show that people can have similar experiences in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set054-q002', '{"sample_answer":"Many people choose sport because it is active, exciting and gives them a clear goal. They can improve their health, learn new skills and enjoy friendly competition. Team sports also help people make friends and feel part of a group. Regular progress makes the activity satisfying and encourages people to continue.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set054-q003', '{"sample_answer":"Football is probably the most popular sport in Vietnam because it is easy to understand, inexpensive to play, and widely broadcast. Major national-team matches create a strong sense of shared excitement. Its popularity also comes from schools, local clubs, and informal street games. However, media attention should not prevent investment in badminton, swimming, athletics, and inclusive sports that may suit different ages and abilities.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set055-q001', '{"sample_answer":"The first picture shows a family enjoying an outdoor picnic, while the second shows customers relaxing in a café. Both pictures show everyday activities, but the places are different. The first scene looks more personal, while the second shows another way to do a similar activity. Overall, they show that people can have similar experiences in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set055-q002', '{"sample_answer":"I would choose the place that offers natural scenery, easy to manage weather, and opportunities for both activity and rest. Personally, I prefer the quieter option because it allows me to walk, take photographs, and recover from city pressure without feeling rushed. However, safety, transport, cost, and the needs of companions are decisive.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set055-q003', '{"sample_answer":"Some people prefer cafés because they offer shelter, comfortable seating, Wi-Fi, toilets, and predictable service regardless of the weather. Outdoor picnics give more space and contact with nature, but require preparation and can be disrupted by rain, insects, or litter. I would choose a picnic in mild weather and a quiet café when convenience, easy access, or serious conversation matters more.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set056-q001', '{"sample_answer":"The first picture shows visitors exploring a museum, while the second shows children using an outdoor playground. Both pictures show everyday activities, but the places are different. The first scene looks more personal, while the second shows another way to do a similar activity. Overall, they show that people can have similar experiences in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set056-q002', '{"sample_answer":"I would choose the place that offers natural scenery, easy to manage weather, and opportunities for both activity and rest. Personally, I prefer the quieter option because it allows me to walk, take photographs, and recover from city pressure without feeling rushed. However, safety, transport, cost, and the needs of companions are decisive.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set056-q003', '{"sample_answer":"I would usually choose the museum because exhibitions can stimulate curiosity and give access to art, science, or history that is difficult to experience elsewhere. Playgrounds are equally important because children need safe spaces for movement, imagination, and social development. A healthy society should fund both: museums preserve knowledge and culture, while playgrounds support everyday physical and emotional health and happiness.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set057-q001', '{"sample_answer":"The first picture shows a family cooking together, while the second shows one person preparing food alone. Both pictures show everyday activities, but the places are different. The first scene looks more personal, while the second shows another way to do a similar activity. Overall, they show that people can have similar experiences in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set057-q002', '{"sample_answer":"I prefer cooking with family because duties can be shared and the process becomes a chance to talk and learn from one another. Cooking alone is faster when schedules are busy and gives complete control over the recipe. For important meals, however, teamwork creates stronger memories and distributes the workload. Clear roles and respectful communication prevent a crowded kitchen from becoming stressful.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set057-q003', '{"sample_answer":"Cooking at home is important because people can choose fresh ingredients, control the amount of salt and oil, and save money. It also gives families a chance to share jobs and talk together. Although cooking takes time, simple planning and basic skills can make home meals healthier and more enjoyable.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set058-q001', '{"sample_answer":"The first picture shows people cooking at an outdoor barbecue, while the second shows a family preparing food indoors. Both pictures show everyday activities, but the places are different. The first scene looks more personal, while the second shows another way to do a similar activity. Overall, they show that people can have similar experiences in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set058-q002', '{"sample_answer":"An outdoor barbecue creates a relaxed social feeling and gives food a distinctive flavour, but it depends on weather, safe equipment, and careful hygiene. Indoor cooking offers better temperature control, cleaner preparation, and access to all kitchen tools. I would choose a barbecue for a weekend gathering in suitable weather, while using the indoor kitchen for complex dishes or occasions requiring greater reliability.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set058-q003', '{"sample_answer":"I would prefer cooking indoors because the kitchen has all the tools I need and the temperature is easier to control. It is also safer in bad weather and more suitable for difficult dishes. Outdoor cooking is fun for social events, but it needs careful food safety, suitable equipment and good weather.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set059-q001', '{"sample_answer":"The first picture shows a warm coastal city under a clear sky, while the second shows a cold city street covered in snow. Both pictures show everyday activities, but the places are different. The first scene looks more personal, while the second shows another way to do a similar activity. Overall, they show that people can have similar experiences in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set059-q002', '{"sample_answer":"A hot coastal city offers beaches, outdoor cafés, and a lively year-round feeling, but humidity and storms may be uncomfortable. A snowy city can feel peaceful and visually beautiful, although heating costs and difficult transport are important disadvantages. I would prefer the coastal city because I enjoy water and outdoor activity, provided the neighbourhood has shade, reliable public transport, and protection from extreme weather.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set059-q003', '{"sample_answer":"I would choose the place that offers natural scenery, easy to manage weather, and opportunities for both activity and rest. Personally, I prefer the quieter option because it allows me to walk, take photographs, and recover from city pressure without feeling rushed. However, safety, transport, cost, and the needs of companions are decisive.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set060-q001', '{"sample_answer":"The first picture shows students working outdoors with notebooks, while the second shows a learner using a tablet in a café. Both pictures show everyday activities, but the places are different. The first scene looks more personal, while the second shows another way to do a similar activity. Overall, they show that people can have similar experiences in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set060-q002', '{"sample_answer":"Compare studying outdoors with notebooks and studying with a tablet in a cafe. The first option generally offers a more direct and traditional experience, while the second tends to give greater convenience, flexibility, or independence. Their how suitable it is depends on cost, safety, time, easy access, and the needs of the people involved.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set060-q003', '{"sample_answer":"Studying outdoors gives fresh air and a refreshing change of scenery, but wind, weather, and background activity can interrupt focus. A tablet in a café gives access to digital resources and charging places and equipment, although noise and notifications are distracting. I prefer a quiet café for structured study, using focus settings and headphones, while reserving outdoor spaces for reading, discussion, or creative brainstorming.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set061-q001', '{"sample_answer":"The first picture shows a person listening to music alone at home, while the second shows a singer performing before a live audience. Both pictures show everyday activities, but the places are different. The first scene looks more personal, while the second shows another way to do a similar activity. Overall, they show that people can have similar experiences in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set061-q002', '{"sample_answer":"Listening at home is affordable, comfortable, and completely under the listener''s control, while a live performance creates energy through sound, visual effects, and a shared audience. I prefer concerts for favourite artists because the feeling can be very memorable, but I use headphones far more often. Cost, travel, crowd size, and hearing protection should all influence the decision.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set061-q003', '{"sample_answer":"Listening at home is affordable, comfortable, and completely under the listener''s control, while a live performance creates energy through sound, visual effects, and a shared audience. I prefer concerts for favourite artists because the feeling can be very memorable, but I use headphones far more often. Cost, travel, crowd size, and hearing protection should all influence the decision.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set062-q001', '{"sample_answer":"The first picture shows employees working together in an office, while the second shows a person working independently from home. Both pictures show everyday activities, but the places are different. The first scene looks more personal, while the second shows another way to do a similar activity. Overall, they show that people can have similar experiences in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set062-q002', '{"sample_answer":"Compare working in an office with working from home. The first option generally offers a more direct and traditional experience, while the second tends to give greater convenience, flexibility, or independence. Their how suitable it is depends on cost, safety, time, easy access, and the needs of the people involved. Overall, I think this is a useful and positive experience.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set062-q003', '{"sample_answer":"Office work supports spontaneous communication, shared equipment, and clearer separation between jobs and home life. Remote work saves commuting time and allows greater flexibility, but isolation and domestic things that break focus can reduce effectiveness. I would prefer a hybrid arrangement, attending the office for teamwork and working from home for concentrated tasks. Success depends on measurable goals, reliable technology, and trust rather than physical presence alone.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set063-q001', '{"sample_answer":"The first picture shows students learning together outdoors, while the second shows children listening to a teacher in a traditional classroom. Both pictures show everyday activities, but the places are different. The first scene looks more personal, while the second shows another way to do a similar activity. Overall, they show that people can have similar experiences in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set063-q002', '{"sample_answer":"Compare learning outdoors with learning in a traditional classroom. The first option generally offers a more direct and traditional experience, while the second tends to give greater convenience, flexibility, or independence. Their how suitable it is depends on cost, safety, time, easy access, and the needs of the people involved. Overall, I think this is a useful and positive experience.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set063-q003', '{"sample_answer":"Outdoor learning makes ideas concrete and memorable through careful watching, movement, and real-world examples, while a traditional classroom gives structure, specialist equipment, and protection from weather. I would combine both rather than choose permanently. Core explanations can happen indoors, followed by practical investigation outside. This approach supports different learners and prevents schools from becoming either too theoretical or insufficiently organised.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set064-q001', '{"sample_answer":"The first picture shows volunteers collecting litter on a beach, while the second shows people planting trees in an open field. Both pictures show everyday activities, but the places are different. The first scene looks more personal, while the second shows another way to do a similar activity. Overall, they show that people can have similar experiences in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set064-q002', '{"sample_answer":"Litter collection produces an quick visible improvement and prevents waste from harming wildlife, while tree planting offers longer-term benefits such as shade, habitats, and carbon storage. I would join a carefully planned tree-planting project, provided suitable native species and maintenance were guaranteed. Planting without follow-up can fail, so environmental activities should be guided by local experts and combined with waste reduction.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set064-q003', '{"sample_answer":"I would choose tree planting because I enjoy practical outdoor work and the result can last for many years. Trees give shade, improve the air and create homes for wildlife. However, the group must choose suitable local trees and care for them afterwards, or the activity may not have a lasting effect.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set065-q001', '{"sample_answer":"The first picture shows a worker in a busy clothing factory, while the second shows employees using computers in an office. Both pictures show everyday activities, but the places are different. The first scene looks more personal, while the second shows another way to do a similar activity. Overall, they show that people can have similar experiences in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set065-q002', '{"sample_answer":"Factory work is practical, physically active, and closely connected to production, but it can involve noise, repetitive movement, and strict safety steps. Office work is cleaner and more flexible, though prolonged screen use may cause stress and inactivity. I would prefer an office with opportunities to visit production areas, because this would combine analytical work with a realistic understanding of how products are made.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set065-q003', '{"sample_answer":"I would prefer an office because it offers stable equipment, protection from bad weather and easy contact with colleagues. I also enjoy organised tasks and computer work. However, sitting all day can be unhealthy, so I would take regular breaks, walk outside at lunchtime and use a comfortable desk and chair.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set066-q001', '{"sample_answer":"The first picture shows a bus travelling through a rural landscape, while the second shows a bicycle used for an individual journey. Both pictures show everyday activities, but the places are different. The first scene looks more personal, while the second shows another way to do a similar activity. Overall, they show that people can have similar experiences in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set066-q002', '{"sample_answer":"Public transport carries many people efficiently and remains practical in bad weather or over longer distances. Cycling is inexpensive, healthy, and emission-free, but safety, heat, and limited luggage can be serious obstacles. For my daily journey, I would cycle on protected routes in mild weather and use a reliable bus when conditions are unsafe. Cities should integrate both options through secure parking and coordinated networks.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set066-q003', '{"sample_answer":"I would choose a bicycle for a short daily journey because it is cheap, healthy and better for the environment. I would not need to wait for a bus or look for parking. However, I would use public transport when the weather is bad, the road is unsafe or the distance is too far.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set067-q001', '{"sample_answer":"The first picture shows a person working alone in an almost empty office, while the second shows colleagues collaborating in a shared workplace. Both pictures show everyday activities, but the places are different. The first scene looks more personal, while the second shows another way to do a similar activity. Overall, they show that people can have similar experiences in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set067-q002', '{"sample_answer":"Working alone allows focus, quick decisions, and clear personal responsibility, while teamwork combines different skills and makes difficult tasks easier to divide. For an important project, I would choose a small, well-organised team because peer review can identify mistakes and improve ideas. However, each member needs a defined role, realistic deadline, and shared communication system to prevent confusion or unequal effort.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set067-q003', '{"sample_answer":"I would prefer working with a small team on an important project. Different members can share ideas, divide the work and check one another''s mistakes. Teamwork can sometimes cause disagreements, so the group needs clear roles and deadlines. For a difficult project, shared skills and support are more useful than working completely alone.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set068-q001', '{"sample_answer":"The first picture shows a dog resting beside its owner, while the second shows a cat playing independently at home. Both pictures show everyday activities, but the places are different. The first scene looks more personal, while the second shows another way to do a similar activity. Overall, they show that people can have similar experiences in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set068-q002', '{"sample_answer":"Dogs generally require regular walks, training, and frequent interaction, while cats are more independent and can adapt better to smaller homes. Both need food, veterinary care, affection, and a safe environment. Children should help with age-suitable tasks because caring for pets develops empathy and responsibility, but adults must retain overall responsibility. An animal should never be acquired merely to teach a temporary lesson.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set068-q003', '{"sample_answer":"Yes, children should help care for pets because it teaches kindness, patience and responsibility. They can give food, provide clean water or help brush the animal. Adults must still guide them and handle difficult tasks. The work should suit the child''s age so that both the child and the pet remain safe.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set069-q001', '{"sample_answer":"The first picture shows a car travelling along a winding road, while the second shows an aircraft flying overhead. Both pictures show everyday activities, but the places are different. The first scene looks more personal, while the second shows another way to do a similar activity. Overall, they show that people can have similar experiences in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set069-q002', '{"sample_answer":"Cars offer door-to-door flexibility, privacy, and useful luggage space, while planes cover long distances far more quickly. Driving can be tiring and at risk to traffic, while flying involves airports, security, baggage limits, and greater expense. For a really long journey, I would choose the plane to save time, then use public transport at the destination. Distance and environmental impact should still be considered.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set069-q003', '{"sample_answer":"For a really long journey, I would choose the plane because it saves many hours and allows more time at the destination. A car offers privacy, flexible stops, and useful luggage space, but driving for an entire day is tiring and traffic can be hard to predict. I would still compare price and emissions, then use public transport after landing to reduce cost and avoid unnecessary car use.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set070-q001', '{"sample_answer":"The first picture shows a car travelling along a winding road, while the second shows an aircraft flying overhead. Both pictures show everyday activities, but the places are different. The first scene looks more personal, while the second shows another way to do a similar activity. Overall, they show that people can have similar experiences in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set070-q002', '{"sample_answer":"Cars offer door-to-door flexibility, privacy, and useful luggage space, while planes cover long distances far more quickly. Driving can be tiring and at risk to traffic, while flying involves airports, security, baggage limits, and greater expense. For a really long journey, I would choose the plane to save time, then use public transport at the destination. Distance and environmental impact should still be considered.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set070-q003', '{"sample_answer":"For a really long journey, I would choose the plane because it saves many hours and allows more time at the destination. A car offers privacy, flexible stops, and useful luggage space, but driving for an entire day is tiring and traffic can be hard to predict. I would still compare price and emissions, then use public transport after landing to reduce cost and avoid unnecessary car use.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set071-q001', '{"sample_answer":"The first picture shows a football match on an outdoor pitch, while the second shows a volleyball game in an indoor sports hall. Both pictures show everyday activities, but the places are different. The first scene looks more personal, while the second shows another way to do a similar activity. Overall, they show that people can have similar experiences in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set071-q002', '{"sample_answer":"Football and volleyball both depend on teamwork, movement, communication, and quick reactions. Football is usually played on a larger field and focuses on running and foot control, while volleyball uses a net and requires careful hand technique and jumping. I would rather play volleyball because the smaller court keeps everyone involved and contact is limited. However, both sports develop fitness, discipline, and teamwork.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set071-q003', '{"sample_answer":"I would rather play volleyball because the smaller court keeps every person involved and the limited physical contact reduces the risk of collision. It still demands quick reactions, accurate technique, communication, and good teamwork. Football is exciting and more widely available, but matches can require greater endurance and larger places and equipment. Volleyball therefore suits me better, although the best choice depends on a person''s fitness and previous experience.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set072-q001', '{"sample_answer":"The first picture shows a colourful selection of nutritious food, while the second shows a meal dominated by burgers, fried food, and sugary drinks. Both pictures show everyday activities, but the places are different. The first scene looks more personal, while the second shows another way to do a similar activity. Overall, they show that people can have similar experiences in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set072-q002', '{"sample_answer":"Healthy food supplies fibre, vitamins, protein, and stable energy, supporting focus, immunity, and long-term disease prevention. People still choose fast food because it is convenient, heavily advertised, predictable, and sometimes cheaper than fresh options. A realistic solution is not complete ban but better planning, clearer healthy diets information, affordable healthy choices, and occasional rather than habitual consumption of highly processed meals.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p3-set072-q003', '{"sample_answer":"Healthy food supplies fibre, vitamins, protein, and stable energy, supporting focus, immunity, and long-term disease prevention. People still choose fast food because it is convenient, heavily advertised, predictable, and sometimes cheaper than fresh options. A realistic solution is not complete ban but better planning, clearer healthy diets information, affordable healthy choices, and occasional rather than habitual consumption of highly processed meals.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic001-q001', '{"sample_answer":"• Describe a time when you faced a difficult question.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic001-q002', '{"sample_answer":"Use CORE STORY 1 + I paused briefly to organise my thoughts, made sure I understood the question and used information from our research. When I was unsure about one detail, I admitted it honestly and offered to check it afterwards.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic001-q003', '{"sample_answer":"Thinking carefully prevents wrong or emotional answers. It helps people understand the real problem, choose useful information and communicate a balanced opinion, which is especially valuable in school discussions, interviews and work meetings. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic002-q001', '{"sample_answer":null,"sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":true,"missing_rubric":true}}'),
  ('speaking-p4-topic002-q002', '{"sample_answer":"Use CORE STORY 1 + Clear goals, a realistic schedule and a fair division of duties were very important. Regular practice showed weak points in our presentation, while useful feedback from my teammates allowed us to improve the final result before the deadline.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic002-q003', '{"sample_answer":"Goals give direction and turn a general wish into clear progress. A realistic target can also help people stay motivated during a difficult task because each small step gives people proof that their work is useful. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic003-q001', '{"sample_answer":null,"sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":true,"missing_rubric":true}}'),
  ('speaking-p4-topic003-q002', '{"sample_answer":"Use CORE STORY 1 + I broke the workload into smaller tasks, put the most important tasks first and gave each task a deadline. I also switched off unnecessary notifications and used a shared calendar so that the entire group could remain on schedule.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic003-q003', '{"sample_answer":"Modern life requires people to balance work or study with family duties, social duties and constant online communication. Also, goals that are not realistic and poor planning can make an already full timetable feel even more tiring. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic004-q001', '{"sample_answer":"• Tell me about something new you learned recently.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic004-q002', '{"sample_answer":"Use CORE STORY 1 + Preparing the presentation taught me to design clearer slides, speak more confidently and use reliable online research tools. I have since applied these skills in other classes, job applications and everyday conversations that require organised explanations.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic004-q003', '{"sample_answer":"Regular learning keeps people ready for change as technology and workplaces change. It also develops confidence, curiosity and problem-solving ability. Even a small practical skill can create new opportunities and make daily tasks more efficient. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic005-q001', '{"sample_answer":null,"sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":true,"missing_rubric":true}}'),
  ('speaking-p4-topic005-q002', '{"sample_answer":"Use CORE STORY 1 + Our plan showed the whole workload and revealed possible problems early. Because we had clear milestones, we could monitor progress and adjust the schedule when one member became unavailable without missing the final deadline.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic005-q003', '{"sample_answer":"Planning turns a large goal into easy to manage actions. It helps people use time and resources well, prepare for possible problems and avoid rushed decisions that may reduce the quality of an important piece of work. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic006-q001', '{"sample_answer":"• Tell me about a time when you worked in a team.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic006-q002', '{"sample_answer":"Use CORE STORY 1 + We communicated openly, divided the work according to individual strengths and checked one another’s progress. We listened to different opinions, supported anyone who fell behind and made major decisions together rather than letting one person dominate.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic006-q003', '{"sample_answer":"Difficult tasks often require different skills and views. Effective teamwork reduces individual pressure, improves problem-solving and teaches people to solve disagreements, communicate and take responsibility for a shared result. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic007-q001', '{"sample_answer":"• Talk about a time you had to put in a lot of effort.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic007-q002', '{"sample_answer":"Use CORE STORY 1 + I focused on the progress we had already made rather than the work that remained. My teammates encouraged me whenever I felt tired, and the desire to produce something we could really be proud of kept me moving forward.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic007-q003', '{"sample_answer":"Special achievements rarely happen immediately. Consistent effort helps people to correct mistakes, build confidence and continue despite setbacks. Even when the outcome is imperfect, sustained practice normally leads to valuable improvement. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic008-q001', '{"sample_answer":null,"sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":true,"missing_rubric":true}}'),
  ('speaking-p4-topic008-q002', '{"sample_answer":"Use CORE STORY 1 + I asked whether the information in a popular online article came from a reliable original study. That question encouraged the group to check the source, replace a weak statistic and make our presentation much more credible.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic008-q003', '{"sample_answer":"A careful question shows what people do not understand and encourages deeper thinking instead of only memorising facts. It can also guide discussion, challenge ideas people accept without checking and help both the speaker and the listener discover a clearer explanation.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic009-q001', '{"sample_answer":null,"sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":true,"missing_rubric":true}}'),
  ('speaking-p4-topic009-q002', '{"sample_answer":"Use CORE STORY 1 + The course gave me regular speaking practice and detailed feedback on pronunciation, grammar and organisation. Group presentations also taught me to express ideas more naturally, respond to unexpected questions and speak despite feeling nervous.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic009-q003', '{"sample_answer":"English gives access to international schools, digital resources and a wider range of careers. It also helps people to communicate while travelling and to build relationships with colleagues or friends from different countries. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic010-q001', '{"sample_answer":null,"sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":true,"missing_rubric":true}}'),
  ('speaking-p4-topic010-q002', '{"sample_answer":"Use CORE STORY 1 + The main challenge was organising people with different schedules while dealing with a large amount of information. I solved it by setting priorities, asking for help when necessary and reviewing our progress every two days.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic010-q003', '{"sample_answer":"Challenges force people to leave familiar routines and develop new strategies. Although they can be uncomfortable, they often strengthen mental strength, reveal hidden abilities and give lessons that make future problems easier to manage. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic011-q001', '{"sample_answer":null,"sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":true,"missing_rubric":true}}'),
  ('speaking-p4-topic011-q002', '{"sample_answer":"Use CORE STORY 1 + A shared document and video-meeting platform allowed us to work from different places, edit the same material and receive updates immediately. Without those tools, arranging meetings and combining everyone’s research would have taken far longer.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic011-q003', '{"sample_answer":"People depend on technology because it saves time, improves access to information and allows instant communication. When used responsibly, it can do repeated tasks and help people study, work and solve problems more effectively. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic012-q001', '{"sample_answer":null,"sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":true,"missing_rubric":true}}'),
  ('speaking-p4-topic012-q002', '{"sample_answer":"Use CORE STORY 1 + As group coordinator, I set deadlines, monitored progress and made sure quieter members could help. I kept a checklist, followed up politely and prepared a backup plan in case a teammate was absent on presentation day.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic012-q003', '{"sample_answer":"Responsibility teaches people to consider how their actions affect others. It builds reliability, self-discipline and trust, qualities that are very important for independent living as well as successful study and jobs. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic013-q001', '{"sample_answer":null,"sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":true,"missing_rubric":true}}'),
  ('speaking-p4-topic013-q002', '{"sample_answer":"Use CORE STORY 1 + Thorough research, simple slides and repeated rehearsal made the presentation successful. I practised transitions with my teammates, prepared for possible questions and concentrated on speaking slowly rather than memorising every sentence.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic013-q003', '{"sample_answer":"Presentation skills help people explain difficult information clearly, persuade an audience and respond confidently to questions. They are useful in classrooms, interviews, meetings and almost any job that involves sharing ideas. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic014-q001', '{"sample_answer":null,"sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":true,"missing_rubric":true}}'),
  ('speaking-p4-topic014-q002', '{"sample_answer":"Use CORE STORY 1 + Volunteering to lead the presentation was new and at first frightening. Afterwards, I felt relieved and really proud because the experience proved that I could remain calm, organise others and communicate effectively under pressure.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic014-q003', '{"sample_answer":"New experiences broaden people’s view and reveal abilities they may not know they possess. They also reduce fear of new situations and make life more varied, provided the risks are considered sensibly. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic015-q001', '{"sample_answer":null,"sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":true,"missing_rubric":true}}'),
  ('speaking-p4-topic015-q002', '{"sample_answer":"Use CORE STORY 1 + When I changed schools, joining a study group helped me settle in quickly. Friendly classmates explained the timetable, shared notes and invited me to work on the presentation, so I gradually felt included rather than isolated.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic015-q003', '{"sample_answer":"A helpful welcome reduces anxiety and allows new students to focus on learning. Schools can assign a buddy, explain routines clearly and create group activities so that friendships form naturally. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic016-q001', '{"sample_answer":null,"sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":true,"missing_rubric":true}}'),
  ('speaking-p4-topic016-q002', '{"sample_answer":"Use CORE STORY 1 + I recently learned that frequent phone notifications can interrupt focus even when people do not answer them. This changed my study routine, so I now silence unnecessary alerts and work in focused periods.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic016-q003', '{"sample_answer":"Information that has not been checked can mislead others and spread extremely quickly online. Checking the author, date and original evidence protects trust and helps people make decisions based on facts rather than attractive but false claims. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic017-q001', '{"sample_answer":null,"sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":true,"missing_rubric":true}}'),
  ('speaking-p4-topic017-q002', '{"sample_answer":"Use CORE STORY 2 + The overnight train, changing scenery and conversations with my friends made the journey memorable. However, limited sleep and the unexpected rain were difficult, so we adjusted our timetable and took short breaks whenever we felt exhausted.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic017-q003', '{"sample_answer":"Long journeys allow people to escape routine, discover new places and spend uninterrupted time with companions. The challenges involved can also create strong memories and a satisfying sense of adventure. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic018-q001', '{"sample_answer":null,"sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":true,"missing_rubric":true}}'),
  ('speaking-p4-topic018-q002', '{"sample_answer":"Use CORE STORY 2 + I enjoyed the cool air, the quiet path and the variety of plants on the hill. A local guide explained how the forest prevented erosion, which helped me understand that natural areas protect communities as well as wildlife.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic018-q003', '{"sample_answer":"Forests absorb carbon, give habitats and protect water and soil. Preserving them also gives future generations places for schools and recreation, while damaged ecosystems can take decades to recover. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic019-q001', '{"sample_answer":null,"sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":true,"missing_rubric":true}}'),
  ('speaking-p4-topic019-q002', '{"sample_answer":"Use CORE STORY 2 + The careful watching deck impressed me most because it offered a complete view of the river, bridges and rapidly growing neighbourhoods. I was also fascinated by the building’s safety systems and energy-efficient design.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic019-q003', '{"sample_answer":"Tall buildings use limited urban land efficiently and place homes, offices and services close together. They can support economic growth, although cities must still give green space, transport and adequate public infrastructure. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic020-q001', '{"sample_answer":null,"sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":true,"missing_rubric":true}}'),
  ('speaking-p4-topic020-q002', '{"sample_answer":"Use CORE STORY 2 + The holiday combined sightseeing with enough time to relax. I enjoyed sharing meals with my friends, exploring at our own pace and temporarily leaving academic deadlines behind, which helped me return home mentally refreshed.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic020-q003', '{"sample_answer":"Regular breaks reduce stress and prevent exhaustion. They give people time to recover physically, reflect on priorities and reconnect with family or friends, often improving focus and the ability to work well afterwards. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic021-q001', '{"sample_answer":null,"sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":true,"missing_rubric":true}}'),
  ('speaking-p4-topic021-q002', '{"sample_answer":"Use CORE STORY 2 + Heavy rain forced us to cancel an outdoor visit and delayed our return to the hotel. Instead of becoming frustrated, we checked the forecast, visited an indoor museum and carried raincoats the following day.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic021-q003', '{"sample_answer":"Weather can change transport, safety and access to outdoor areas. Checking forecasts, carrying suitable clothing and keeping a backup plan allow people to respond calmly instead of taking unnecessary risks. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic022-q001', '{"sample_answer":null,"sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":true,"missing_rubric":true}}'),
  ('speaking-p4-topic022-q002', '{"sample_answer":"Use CORE STORY 2 + I tried a supervised zip-line activity on the forested hill. Before starting, I was anxious about the height, but the instructor checked the equipment carefully. Afterwards, I felt excited and proud that I had controlled my fear.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic022-q003', '{"sample_answer":"Extreme sports give excitement, challenge and a strong sense of achievement. Some people enjoy testing their limits and escaping routine, although professional guidance and proper safety equipment are very important. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic023-q001', '{"sample_answer":null,"sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":true,"missing_rubric":true}}'),
  ('speaking-p4-topic023-q002', '{"sample_answer":"Use CORE STORY 2 + I learned how Da Nang combines modern development with local traditions. The riverside architecture showed recent growth, while the museum and markets introduced us to regional history, food and everyday customs.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic023-q003', '{"sample_answer":"Culture is easier to understand when people observe daily life directly. Visiting streets, museums and local businesses exposes travellers to traditions and viewpoints that cannot be experienced fully through books or screens. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic024-q001', '{"sample_answer":"• Talk about a historic building you have visited. Say where it is, what it looks like, what you learned there, and explain why historic buildings should be protected.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic024-q002', '{"sample_answer":"Use CORE STORY 2 + The old building impressed me with its weathered yellow walls, wooden details and photographs of the city decades ago. I learned that it had survived major historical changes and once served the local community.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic024-q003', '{"sample_answer":"Historic buildings preserve evidence of architecture, identity and shared memory. Restoring them can support schools and tourism, while demolition permanently removes cultural information that modern replicas cannot really replace. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic025-q001', '{"sample_answer":"• Tell me about a memorable trip you had.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic025-q002', '{"sample_answer":"Use CORE STORY 2 + The experience taught me to respect local customs, plan transport carefully and remain flexible when difficulties arise. It also showed me that speaking with residents often reveals more than following a standard tourist schedule.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic025-q003', '{"sample_answer":"Travelling develops independence, cultural awareness and practical problem-solving. It allows people to compare different ways of life, challenge ideas people accept without checking and return home with knowledge that is memorable because it was experienced directly. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic026-q001', '{"sample_answer":null,"sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":true,"missing_rubric":true}}'),
  ('speaking-p4-topic026-q002', '{"sample_answer":"Use CORE STORY 2 + When my phone signal disappeared, I stayed with my friends, returned to the last familiar street and asked a shopkeeper for directions. We also photographed a nearby sign so that we could confirm the route later.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic026-q003', '{"sample_answer":"Digital maps give real-time directions, transport information and nearby landmarks. Offline maps and location sharing also improve safety, although people should still notice street names and avoid relying completely on a battery-powered device. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic027-q001', '{"sample_answer":null,"sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":true,"missing_rubric":true}}'),
  ('speaking-p4-topic027-q002', '{"sample_answer":"Use CORE STORY 2 + I enjoyed a fast roller coaster because it was thrilling and gave my friends and me something to laugh about afterwards. The park’s evening lights and lively feeling also made the visit feel special.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic027-q003', '{"sample_answer":"Amusement parks offer entertainment for different ages in one organised place. Families and young people can share unusual experiences, celebrate special occasions and enjoy a temporary escape from their normal routines. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic028-q001', '{"sample_answer":null,"sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":true,"missing_rubric":true}}'),
  ('speaking-p4-topic028-q002', '{"sample_answer":"Use CORE STORY 3 + I most enjoyed the relaxed conversation and the chance to prepare for the event together. Because we were not rushing, we could share personal news, exchange ideas and strengthen our friendship in a natural way.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic028-q003', '{"sample_answer":"Helpful friendships reduce loneliness and give people a safe place to discuss problems. Spending time together also builds shared memories and maintains trust, especially when busy schedules make regular contact difficult. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic029-q001', '{"sample_answer":"• Describe a time when you helped someone.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic029-q002', '{"sample_answer":"Use CORE STORY 3 + I patiently demonstrated the drawing activity and introduced the shy child to two friendly people. She gradually became confident, completed a colourful picture and stayed involved instead of sitting alone.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic029-q003', '{"sample_answer":"Practical help can reduce another person’s stress and give them confidence to act independently. It also encourages empathy and teamwork, creating communities in which people are more willing to support one another. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic030-q001', '{"sample_answer":null,"sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":true,"missing_rubric":true}}'),
  ('speaking-p4-topic030-q002', '{"sample_answer":"Use CORE STORY 3 + I learned that children respond best to clear instructions, encouragement and activities with some choice. I also discovered that adults need patience because children develop at different speeds and may express confidence in different ways.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic030-q003', '{"sample_answer":"Well-designed activities develop creativity, communication and physical teamwork. They also teach children to share, follow rules and solve problems with others while giving them a safe and enjoyable way to build confidence. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic031-q001', '{"sample_answer":"• Tell me about a time when you laughed a lot with a friend.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic031-q002', '{"sample_answer":"Use CORE STORY 3 + My friend accidentally wore a child’s paper crown while seriously explaining the event schedule, and neither of us noticed at first. The contrast was so unexpected that we laughed uncontrollably and still mention it today.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic031-q003', '{"sample_answer":"Laughter reduces tension and helps people feel comfortable with one another. Shared humour creates positive memories, makes difficult situations easier to handle and can strengthen a friendship without requiring an expensive activity. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic032-q001', '{"sample_answer":null,"sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":true,"missing_rubric":true}}'),
  ('speaking-p4-topic032-q002', '{"sample_answer":"Use CORE STORY 3 + We became friends because we were assigned to the same activity and discovered similar interests in technology and language learning. Working towards a shared purpose made conversation easy, and we exchanged contact details afterwards.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic032-q003', '{"sample_answer":"New friendships give emotional support and expose people to different ideas and experiences. They are especially valuable after moving somewhere new because they create a sense of belonging and reduce isolation. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic033-q001', '{"sample_answer":"• Talk about a time you received good news.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic033-q002', '{"sample_answer":"Use CORE STORY 3 + After the event, the organiser told us that attendance had exceeded what people expect and the centre wanted to repeat the programme. The news lifted my mood and encouraged me to volunteer for the next event immediately.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic033-q003', '{"sample_answer":"Sharing positive news allows others to celebrate and strengthens emotional connections. It can also inspire hope, recognise shared effort and motivate people who contributed to continue supporting a worth doing project. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic034-q001', '{"sample_answer":"• Tell me about a time when you had a different opinion from an older or younger person.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic034-q002', '{"sample_answer":"Use CORE STORY 3 + I learned that older and younger people may approach technology differently but can still learn from one another. When opinions differed, I asked questions, avoided dismissive language and focused on the practical outcome we both wanted.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic034-q003', '{"sample_answer":"Different generations grow up with distinct technology, what people expect and social conditions. Respectful communication allows them to exchange experience and new ideas, preventing fixed ideas from becoming unnecessary conflict. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic035-q001', '{"sample_answer":"• Tell me about a time when you received or gave a special gift.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic035-q002', '{"sample_answer":"Use CORE STORY 3 + The handmade card was inexpensive, but it was special because the child had created it herself to express genuine gratitude. It reminded me that the time and meaning behind a gift can matter more than its price.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic035-q003', '{"sample_answer":"Gifts mark celebrations, express appreciation and show that someone has been remembered. On birthdays, holidays or personal milestones, a careful present can communicate affection when ordinary words seem insufficient. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic036-q001', '{"sample_answer":null,"sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":true,"missing_rubric":true}}'),
  ('speaking-p4-topic036-q002', '{"sample_answer":"Use CORE STORY 3 + When I struggled to organise the timetable, an experienced volunteer simplified the schedule and contacted several people for me. Her support reduced my stress and allowed me to focus on assisting visitors effectively.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic036-q003', '{"sample_answer":"Asking for help prevents small difficulties from becoming serious problems and helps people to learn from others. Accepting support is not weakness. it often shows realistic judgement and protects the quality of shared work. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic037-q001', '{"sample_answer":null,"sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":true,"missing_rubric":true}}'),
  ('speaking-p4-topic037-q002', '{"sample_answer":"Use CORE STORY 3 + The international student described community events in her country and taught us a simple children’s game. I learned that traditions may differ, but hospitality, humour and the desire to help are widely shared.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic037-q003', '{"sample_answer":"Meeting people from other countries challenges fixed ideas and develops cultural sensitivity. It also improves communication skills and helps people understand global issues through personal experience rather than second-hand ideas people accept without checking. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic038-q001', '{"sample_answer":null,"sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":true,"missing_rubric":true}}'),
  ('speaking-p4-topic038-q002', '{"sample_answer":"Use CORE STORY 3 + I shared my tablet and presentation materials with another volunteer because her phone screen was too small for the activity. Sharing the equipment allowed both groups to continue without delay and created a cooperative feeling.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic038-q003', '{"sample_answer":"Sharing resources can reduce waste, solve practical problems and show trust. In relationships and communities, it reminds people that teamwork often produces a better result than protecting every advantage for themselves. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic039-q001', '{"sample_answer":null,"sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":true,"missing_rubric":true}}'),
  ('speaking-p4-topic039-q002', '{"sample_answer":"Use CORE STORY 3 + The organiser complimented me on explaining the activity patiently to the children. I felt appreciated and more confident because the comment recognised a specific action rather than offering empty praise.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic039-q003', '{"sample_answer":"A sincere compliment reinforces positive behaviour and can improve someone’s confidence at very little cost. It is most effective when it is specific, honest and delivered without comparing the person negatively with others. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic040-q001', '{"sample_answer":null,"sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":true,"missing_rubric":true}}'),
  ('speaking-p4-topic040-q002', '{"sample_answer":"Use CORE STORY 3 + The event gave children a safe creative activity, helped older residents become more comfortable with technology and connected neighbours who had rarely spoken. It also taught volunteers to organise resources and respond to different needs.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic040-q003', '{"sample_answer":"Volunteering addresses local needs while developing empathy, teamwork and practical skills. It also gives people a stronger connection to their community and shows that small contributions can produce a special shared impact. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic041-q001', '{"sample_answer":null,"sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":true,"missing_rubric":true}}'),
  ('speaking-p4-topic041-q002', '{"sample_answer":"Use CORE STORY 4 + I at first felt frustrated because the laptop seemed very important for my studies. After calming down, I researched options, repaired the old device temporarily and created a savings plan instead of making an impulsive financial decision.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic041-q003', '{"sample_answer":"Scarcity can make an item appear more valuable, while advertising and social comparison create goals that are not realistic. People may also connect possessions with status or happiness, even when a cheaper option would meet their actual needs. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic042-q001', '{"sample_answer":"• Tell me about a time when you tried to save money.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic042-q002', '{"sample_answer":"Use CORE STORY 4 + A written target, automatic weekly transfers and a spending record kept me disciplined. I reduced takeaway meals and optional subscriptions, but still allowed a small entertainment budget so the plan remained realistic.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic042-q003', '{"sample_answer":"Savings give protection against emergencies and make schools, travel or major purchases possible without excessive debt. Starting early also develops self-control and allows compound interest to work over a longer period. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic043-q001', '{"sample_answer":"• Talk about a time you wanted to buy something but couldn''t.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic043-q002', '{"sample_answer":"Use CORE STORY 4 + I wanted the laptop because the old one crashed during online classes and could not run the software required for my projects. A dependable device would improve both my the ability to work well and future jobs opportunities.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic043-q003', '{"sample_answer":"People may pay more for durability, convenience or a product connected to an important goal. However, emotion, advertising and social pressure can also encourage overspending, so comparing value and long-term use is very important. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic044-q001', '{"sample_answer":"• Describe a time when you had many options to choose from.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic044-q002', '{"sample_answer":"Use CORE STORY 5 + I listed the advantages, costs and travel time of several internships, then ranked the factors that mattered most. Discussing the options with a lecturer helped me choose the role offering useful experience without damaging my studies.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic044-q003', '{"sample_answer":"A large number of options increases comparison and fear of regret. People may focus on minor differences, postpone decisions or become dissatisfied afterwards, so clear priorities and a reasonable deadline are helpful. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic045-q001', '{"sample_answer":"• Talk about a time you were in a hurry.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic045-q002', '{"sample_answer":"Use CORE STORY 5 + Because I rushed, I forgot an important document and entered the wrong office area. I arrived stressed rather than prepared and had to ask a classmate to send the missing file electronically.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic045-q003', '{"sample_answer":"People often hurry because of overloaded schedules, poor time estimates and pressure to respond immediately. Traffic and digital things that break focus also cause delays, while goals that are not realistic leave too little time between duties. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic046-q001', '{"sample_answer":null,"sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":true,"missing_rubric":true}}'),
  ('speaking-p4-topic046-q002', '{"sample_answer":"Use CORE STORY 5 + I disliked making routine data checks, but completing them taught me patience and attention to detail. I in the end understood that less exciting tasks can protect a team from larger errors and support more creative work.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic046-q003', '{"sample_answer":"Not every responsibility is enjoyable, yet health, study and work all require discipline. Completing necessary tasks builds reliability and often creates future freedom by preventing neglected problems from becoming more serious. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic047-q001', '{"sample_answer":null,"sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":true,"missing_rubric":true}}'),
  ('speaking-p4-topic047-q002', '{"sample_answer":"Use CORE STORY 5 + When I sleep for seven to eight hours, I focus better and respond more patiently. If I stay up using my phone, I feel tired, forget small details and depend too heavily on caffeine the next day.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic047-q003', '{"sample_answer":"Sleep supports memory, physical recovery and emotional control. Chronic sleep loss weakens focus and may damage long-term health, so a regular bedtime is a practical investment rather than wasted time. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic048-q001', '{"sample_answer":null,"sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":true,"missing_rubric":true}}'),
  ('speaking-p4-topic048-q002', '{"sample_answer":"Use CORE STORY 5 + After entering the restricted area, I apologised, returned immediately and read the safety notice carefully. My supervisor accepted the mistake but reminded me that repeated carelessness could put equipment and staff at risk.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic048-q003', '{"sample_answer":"Clear rules protect safety, fairness and predictable teamwork. Although some rules should be reviewed when situation change, ignoring them without discussion can harm others and weaken trust within a community or workplace. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic049-q001', '{"sample_answer":null,"sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":true,"missing_rubric":true}}'),
  ('speaking-p4-topic049-q002', '{"sample_answer":"Use CORE STORY 5 + I stopped immediately, listened to the explanation and apologised for overlooking the sign. Rather than becoming defensive, I asked where visitors were permitted to wait and followed the supervisor’s guidance.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic049-q003', '{"sample_answer":"Respecting another person’s reasonable request protects comfort, privacy and safety. It also prevents conflict and shows that communication is more important than insisting on personal convenience. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic050-q001', '{"sample_answer":"• Tell me about a time when you wore formal clothes. Say what the occasion was, what you wore, how you felt, and explain whether formal clothes are still important today.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic050-q002', '{"sample_answer":"Use CORE STORY 5 + For the internship interview, I wore a navy shirt, dark trousers and simple shoes. The outfit was comfortable but professional, so it improved my posture and confidence without making me feel as though I was pretending to be someone else.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic050-q003', '{"sample_answer":"Clothing communicates awareness of context before a conversation begins. Formal dress remains useful for interviews and ceremonies, although cleanliness, how suitable it is and confident behaviour usually matter more than expensive brands. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic051-q001', '{"sample_answer":"• Tell me about a time when you met a rude person.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic051-q002', '{"sample_answer":"Use CORE STORY 5 + I kept my voice calm, said the customer’s frustration and explained what help was available. When the behaviour continued, I set a polite boundary and asked an experienced colleague to support the conversation.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic051-q003', '{"sample_answer":"Politeness prevents emotion from controlling the discussion and makes a practical solution more likely. People can disagree firmly without insults. respectful language protects dignity and avoids turning one problem into a personal conflict. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic052-q001', '{"sample_answer":null,"sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":true,"missing_rubric":true}}'),
  ('speaking-p4-topic052-q002', '{"sample_answer":"Use CORE STORY 5 + Preparing my bag and clothes at night made mornings less stressful, while a fixed bedtime improved my focus. The routine at first felt restrictive, but it in the end gave me more control over study and work.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic052-q003', '{"sample_answer":"A routine should support current priorities rather than continue automatically. New jobs, health needs or family duties may require adjustment, and small deliberate changes can prevent stress and improve long-term performance. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic053-q001', '{"sample_answer":null,"sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":true,"missing_rubric":true}}'),
  ('speaking-p4-topic053-q002', '{"sample_answer":"Use CORE STORY 5 + A friend left an tiring retail job for a junior office role. At first, the new systems were confusing, but regular hours improved his health and the training created a clearer career direction.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic053-q003', '{"sample_answer":"People change jobs for better development, income, flexibility or workplace culture. Others need to relocate or protect their health and happiness. A careful change can be positive, although financial and training risks should be considered. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic054-q001', '{"sample_answer":null,"sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":true,"missing_rubric":true}}'),
  ('speaking-p4-topic054-q002', '{"sample_answer":"Use CORE STORY 5 + While waiting for the internship result, I felt anxious and checked my email too frequently. I in the end focused on coursework, prepared for other applications and reminded myself that the decision was outside my control.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic054-q003', '{"sample_answer":"Patience helps people tolerate uncertainty without making careless decisions. It supports learning, relationships and long-term goals because many worth doing results require gradual progress rather than quick reward. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic055-q001', '{"sample_answer":"• Tell me about a sports event you watched or took part in.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic055-q002', '{"sample_answer":"Use CORE STORY 6 + The final remained close until the last few minutes, and both teams played with determination. Cheering with my classmates created a shared sense of excitement, even though none of us personally knew the players.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic055-q003', '{"sample_answer":"Sport combines skill, uncertainty and strong emotion. Watching creates social connection, while participating improves fitness, discipline and teamwork. These benefits make sport appealing across ages and cultures. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic056-q001', '{"sample_answer":null,"sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":true,"missing_rubric":true}}'),
  ('speaking-p4-topic056-q002', '{"sample_answer":"Use CORE STORY 6 + I most enjoyed hearing the band perform live because the sound, lighting and audience energy were far more powerful than a recording. Discovering a talented local group also made the experience feel personal.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic056-q003', '{"sample_answer":"Music festivals allow young people to socialise, express identity and experience several performers in one place. They also give a memorable break from routine, although organisers must manage safety, cost and noise responsibly. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic057-q001', '{"sample_answer":null,"sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":true,"missing_rubric":true}}'),
  ('speaking-p4-topic057-q002', '{"sample_answer":"Use CORE STORY 6 + The science book explained how everyday technology influences attention and learning. It gave me practical ideas for reducing things that break focus and showed me how evidence can challenge ideas people accept without checking that at first seem reasonable.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic057-q003', '{"sample_answer":"Books give sustained explanations that short online posts often lack. Reading develops focus, vocabulary and imagination, and it allows people to examine another person’s reasoning at their own pace. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic058-q001', '{"sample_answer":"• Tell me about a work of art that impressed you. Say what it was, where you saw it, what you liked about it, and explain why art can be valuable in people''s lives.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic058-q002', '{"sample_answer":"Use CORE STORY 6 + The cityscape at first appeared peaceful, but closer inspection revealed isolated figures surrounded by bright advertisements. It made me think about how modern cities can feel both connected and lonely at the same time.","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}'),
  ('speaking-p4-topic058-q003', '{"sample_answer":"Art preserves culture, communicates emotions and encourages viewers to interpret new experiences. It can start important conversations, offer comfort and help people notice aspects of society that ordinary language may not express effectively. + COMMON CONCLUSION","sample_transcript":null,"key_vocabulary":[],"rubric":null,"status":{"missing_image":false,"missing_sample_answer":false,"missing_rubric":true}}')
) AS a(question_source_key, solution_data)
